  1	'use strict';
  2	
  3	/**
  4	 * GameComponent - the component named in the ComponentDiagram (spec.json view 9)
  5	 * and in the traceability matrix (FR-1, NFR-1).
  6	 *
  7	 *   artifact GameComponent
  8	 *   artifact QuestionComponent
  9	 *   artifact UserComponent
 10	 *   artifact AdminComponent
 11	 *   GameComponent -- QuestionComponent
 12	 *   GameComponent -- UserComponent
 13	 *   GameComponent -- AdminComponent
 14	 *
 15	 * Responsibilities (spec section C/D): "game logic and user interaction. It owns
 16	 * the game state data."
 17	 *
 18	 * Recommended stack (spec section D): Node.js 18, Express.js 4, PostgreSQL 14,
 19	 * Redis 6, RabbitMQ 3, Elasticsearch 7, OAuth2, Prometheus 2, Jenkins 2,
 20	 * Docker 20, Terraform 1.
 21	 */
 22	const shared = require('@spacefractions/shared');
 23	const { config } = shared;
 24	
 25	const { GameService } = require('./service/gameService');
 26	const { GameRepository } = require('./repository/gameRepository');
 27	const { QuestionComponentClient } = require('./clients/questionClient');
 28	const openApiDocument = require('./openapiDocument');
 29	const { ADMIN_BASE_PATH, createAdminRoutes } = require('./routes/adminRoutes');
 30	
 31	class GameComponent {
 32	  constructor(options = {}) {
 33	    this.name = 'GameComponent';
 34	    this.config = config;
 35	    this.logger = options.logger || shared.createLogger(this.name);
 36	    this.metrics = options.metrics || shared.observability.createMetrics(this.name);
 37	
 38	    // PostgreSQL 14 - owns game state (spec section D data model).
 39	    this.pool = options.pool || shared.postgres.createPool(this.logger, {
 40	      schema: config.schemas.game,
 41	    });
 42	
 43	    // Redis 6 - "Cache game state in Redis".
 44	    this.redis = options.redis || shared.redis.createRedisClient(this.logger);
 45	    this.cache = options.cache || shared.redis.createCacheAside(this.redis, this.logger, {
 46	      prefix: 'spacefractions:game',
 47	      ttlSeconds: config.redis.gameStateTtlSeconds,
 48	    });
 49	
 50	    // RabbitMQ 3 - event publishing.
 51	    this.messaging = options.messaging || shared.messaging.createMessaging(this.logger, {
 52	      component: this.name,
 53	    });
 54	
 55	    // Elasticsearch 7 is owned by QuestionComponent, but GameComponent indexes
 56	    // completed sessions for the analytics/engagement use case named in
 57	    // section G ("user engagement"). Optional: degrades to a no-op.
 58	    this.search = options.search || shared.search.createSearchClient(this.logger, 'spacefractions-games');
 59	
 60	    this.repository = options.repository || new GameRepository({
 61	      pool: this.pool,
 62	      cache: this.cache,
 63	      logger: this.logger,
 64	      schema: config.schemas.game,
 65	      metrics: this.metrics,
 66	    });
 67	
 68	    this.questionClient = options.questionClient || new QuestionComponentClient({
 69	      baseUrl: shared.http.createServiceRegistry(config).question,
 70	      logger: this.logger,
 71	      metrics: this.metrics,
 72	    });
 73	
 74	    this.service = options.service || new GameService({
 75	      repository: this.repository,
 76	      questionClient: this.questionClient,
 77	      messaging: this.messaging,
 78	      metrics: this.metrics,
 79	      logger: this.logger,
 80	      config,
 81	    });
 82	
 83	    this.app = this.buildApp();
 84	  }
 85	
 86	  buildApp() {
 87	    const { createGameRoutes } = require('./routes/gameRoutes');
 88	    const app = shared.http.createApp({
 89	      componentName: this.name,
 90	      logger: this.logger,
 91	      metrics: this.metrics,
 92	      openApiDocument,
 93	      readyChecks: [
 94	        // PostgreSQL is authoritative -> required for readiness (ASR-1).
 95	        { name: 'postgres', check: () => shared.postgres.ping(this.pool), required: true },
 96	        // Redis and RabbitMQ degrade gracefully -> reported but not required (NFR-1).
 97	        { name: 'redis', check: () => this.redis.isReady, required: false },
 98	        { name: 'rabbitmq', check: () => this.messaging.isConnected(), required: false },
 99	        { name: 'question-component', check: () => this.questionClient.health(), required: false },
100	      ],
101	    });
102	
103	    app.use(createGameRoutes({ service: this.service, logger: this.logger }));
104	
105	    // Admin surface: ComponentDiagram wires GameComponent -- AdminComponent.
106	    app.use(ADMIN_BASE_PATH, createAdminRoutes({ service: this.service, logger: this.logger }));
107	
108	    return app;
109	  }
110	
111	  async start() {
112	    const { port, host } = config.game;
113	    this.server = this.app.listen(port, host, () => {
114	      this.logger.info(
115	        { port, host, component: this.name },
116	        `${this.name} listening`,
117	      );
118	    });
119	    return this.server;
120	  }
121	
122	  async stop() {
123	    if (this.server) await new Promise((resolve) => this.server.close(resolve));
124	    await this.messaging.close();
125	    try {
126	      await this.redis.quit();
127	    } catch (_) {
128	      /* already closed */
129	    }
130	    await this.pool.end();
131	  }
132	}
133	
134	module.exports = { GameComponent };

  1	'use strict';
  2	
  3	/**
  4	 * In-memory fakes for the external systems, so unit tests run with no
  5	 * PostgreSQL / Redis / RabbitMQ / Elasticsearch running.
  6	 *
  7	 * These live in tests/ (not src/) deliberately: production code always talks to
  8	 * the real clients in shared/src.
  9	 */
 10	
 11	/** Minimal pg Pool stand-in backed by arrays and a simple SQL matcher. */
 12	class FakePgPool {
 13	  constructor() {
 14	    this.games = []; // { id, game_uid, game_state, updated_at }
 15	    this.questions = []; // raw rows
 16	    this.users = [];
 17	    this.refreshTokens = [];
 18	    this.queries = [];
 19	    this.nextGameId = 1;
 20	    this.nextQuestionId = 1;
 21	    this.nextUserId = 1;
 22	    this.failNext = null;
 23	  }
 24	
 25	  on() {
 26	    return this;
 27	  }
 28	
 29	  async end() {
 30	    return undefined;
 31	  }
 32	
 33	  async query(sql, params = []) {
 34	    this.queries.push({ sql: String(sql).replace(/\s+/g, ' ').trim(), params });
 35	    if (this.failNext) {
 36	      const err = this.failNext;
 37	      this.failNext = null;
 38	      throw err;
 39	    }
 40	    const s = String(sql).replace(/\s+/g, ' ').trim();
 41	
 42	    // --- health / durability probes ---
 43	    if (/^SELECT 1 AS ok/.test(s)) return { rows: [{ ok: 1 }] };
 44	    if (/pg_stat_replication/.test(s)) return { rows: [{ standbys: 1 }] };
 45	    if (/pg_current_wal_lsn/.test(s)) {
 46	      return { rows: [{ wal_lsn: '0/16B3748', captured_at: new Date().toISOString() }] };
 47	    }
 48	
 49	    // --- game.games ---
 50	    if (/INSERT INTO game\.games/i.test(s)) {
 51	      const [gameUid, gameState] = params;
 52	      const existing = this.games.find((g) => g.game_uid === gameUid);
 53	      if (existing) {
 54	        existing.game_state = JSON.parse(gameState);
 55	        existing.updated_at = new Date().toISOString();
 56	        return { rows: [{ id: existing.id, game_uid: gameUid, updated_at: existing.updated_at }] };
 57	      }
 58	      const row = {
 59	        id: this.nextGameId++,
 60	        game_uid: gameUid,
 61	        game_state: JSON.parse(gameState),
 62	        updated_at: new Date().toISOString(),
 63	      };
 64	      this.games.push(row);
 65	      return { rows: [{ id: row.id, game_uid: row.game_uid, updated_at: row.updated_at }] };
 66	    }
 67	    if (/SELECT game_state FROM game\.games/i.test(s)) {
 68	      const row = this.games.find((g) => g.game_uid === params[0]);
 69	      return { rows: row ? [{ game_state: row.game_state }] : [] };
 70	    }
 71	    if (/COUNT\(\*\)::int AS count FROM game\.games WHERE/i.test(s)) {
 72	      return { rows: [{ count: this.games.filter((g) => g.game_state.state === params[0]).length }] };
 73	    }
 74	    if (/COUNT\(\*\)::int AS count FROM game\.games/i.test(s)) {
 75	      return { rows: [{ count: this.games.length }] };
 76	    }
 77	    if (/FROM game\.games WHERE \(\$1::text IS NULL/i.test(s)) {
 78	      const rows = this.games
 79	        .map((g) => ({
 80	          game_uid: g.game_uid,
 81	          score: g.game_state.score,
 82	          state: g.game_state.state,
 83	          username: g.game_state.user ? g.game_state.user.username : null,
 84	          updated_at: g.updated_at,
 85	        }))
 86	        .sort((a, b) => b.score - a.score)
 87	        .slice(0, params[1]);
 88	      return { rows };
 89	    }
 90	
 91	    // --- question.questions ---
 92	    if (/INSERT INTO question\.questions/i.test(s)) {
 93	      const [uid, prompt, options, correctOption, difficulty, weight, tags, active] = params;
 94	      const row = {
 95	        id: this.nextQuestionId++,
 96	        question_uid: uid,
 97	        prompt,
 98	        options: JSON.parse(options),
 99	        correct_option: correctOption,
100	        difficulty,
101	        weight,
102	        tags: JSON.parse(tags),
103	        active,
104	        version: 1,
105	        created_at: new Date().toISOString(),
106	        updated_at: new Date().toISOString(),
107	      };
108	      this.questions.push(row);
109	      return { rows: [{ id: row.id, question_uid: uid, created_at: row.created_at, updated_at: row.updated_at, version: 1 }] };
110	    }
111	    if (/INSERT INTO question\.questions[\s\S]*ON CONFLICT/i.test(s)) {
112	      return { rows: [] };
113	    }
114	    if (/SELECT \* FROM question\.questions WHERE question_uid = \$1 AND active = TRUE/i.test(s)) {
115	      const row = this.questions.find((q) => q.question_uid === params[0] && q.active);
116	      return { rows: row ? [row] : [] };
117	    }
118	    if (/UPDATE question\.questions[\s\S]*SET prompt = \$2/i.test(s)) {
119	      const row = this.questions.find((q) => q.question_uid === params[0]);
120	      if (!row) return { rows: [] };
121	      row.prompt = params[1];
122	      row.options = JSON.parse(params[2]);
123	      row.correct_option = params[3];
124	      row.difficulty = params[4];
125	      row.weight = params[5];
126	      row.tags = JSON.parse(params[6]);
127	      row.active = params[7];
128	      row.version += 1;
129	      row.updated_at = new Date().toISOString();
130	      return { rows: [{ id: row.id, question_uid: row.question_uid, version: row.version }] };
131	    }
132	    if (/UPDATE question\.questions SET active = FALSE/i.test(s)) {
133	      const row = this.questions.find((q) => q.question_uid === params[0]);
134	      if (!row) return { rows: [] };
135	      row.active = false;
136	      return { rows: [{ question_uid: row.question_uid }] };
137	    }
138	    if (/SELECT \* FROM question\.questions\s+WHERE \(\$1::text IS NULL/i.test(s)) {
139	      const [difficulty, activeOnly, limit] = params;
140	      let rows = this.questions.filter((q) => (activeOnly ? q.active : true));
141	      if (difficulty) rows = rows.filter((q) => q.difficulty === difficulty);
142	      return { rows: rows.slice(0, limit) };
143	    }
144	    if (/COUNT\(\*\)::int AS count FROM question\.questions/i.test(s)) {
145	      const activeOnly = params[0];
146	      return { rows: [{ count: activeOnly ? this.questions.filter((q) => q.active).length : this.questions.length }] };
147	    }
148	
149	    // --- user_svc ---
150	    if (/INSERT INTO user_svc\.users/i.test(s)) {
151	      const [uid, username, role, hash, salt, email, displayName, active] = params;
152	      const row = {
153	        id: this.nextUserId++,
154	        user_uid: uid,
155	        username,
156	        role,
157	        password_hash: hash,
158	        password_salt: salt,
159	        email,
160	        display_name: displayName,
161	        active,
162	        created_at: new Date().toISOString(),
163	        updated_at: new Date().toISOString(),
164	      };
165	      this.users.push(row);
166	      return { rows: [{ id: row.id, user_uid: uid }] };
167	    }
168	    if (/SELECT \* FROM user_svc\.users WHERE lower\(username\)/i.test(s)) {
169	      const row = this.users.find((u) => u.username.toLowerCase() === String(params[0]).toLowerCase());
170	      return { rows: row ? [row] : [] };
171	    }
172	    if (/SELECT \* FROM user_svc\.users WHERE user_uid = \$1/i.test(s)) {
173	      const row = this.users.find((u) => u.user_uid === params[0]);
174	      return { rows: row ? [row] : [] };
175	    }
176	    if (/SELECT \* FROM user_svc\.users ORDER BY created_at/i.test(s)) {
177	      return { rows: this.users.slice(params[1], params[1] + params[0]) };
178	    }
179	    if (/COUNT\(\*\)::int AS count FROM user_svc\.users/i.test(s)) {
180	      return { rows: [{ count: this.users.length }] };
181	    }
182	    if (/UPDATE user_svc\.users SET active/i.test(s)) {
183	      const row = this.users.find((u) => u.user_uid === params[0]);
184	      if (!row) return { rows: [] };
185	      row.active = params[1];
186	      return { rows: [{ user_uid: row.user_uid }] };
187	    }
188	    if (/INSERT INTO user_svc\.refresh_tokens/i.test(s)) {
189	      this.refreshTokens.push({ user_uid: params[0], token_hash: params[1], expires_at: params[2], revoked: false });
190	      return { rows: [] };
191	    }
192	    if (/SELECT \* FROM user_svc\.refresh_tokens/i.test(s)) {
193	      const now = Date.now();
194	      const row = this.refreshTokens.find(
195	        (t) => t.token_hash === params[0] && !t.revoked && Date.parse(t.expires_at) > now,
196	      );
197	      return { rows: row ? [row] : [] };
198	    }
199	    if (/UPDATE user_svc\.refresh_tokens SET revoked = TRUE/i.test(s)) {
200	      const row = this.refreshTokens.find((t) => t.token_hash === params[0]);
201	      if (row) row.revoked = true;
202	      return { rowCount: row ? 1 : 0 };
203	    }
204	    if (/DELETE FROM user_svc\.refresh_tokens/i.test(s)) {
205	      const before = this.refreshTokens.length;
206	      this.refreshTokens = this.refreshTokens.filter(
207	        (t) => !t.revoked && Date.parse(t.expires_at) > Date.now(),
208	      );
209	      return { rowCount: before - this.refreshTokens.length };
210	    }
211	    if (/SELECT \* FROM user_svc\.users/i.test(s)) {
212	      return { rows: this.users };
213	    }
214	
215	    throw new Error(`FakePgPool: unhandled query -> ${s}`);
216	  }
217	}
