219	/** Redis stand-in implementing only the commands createCacheAside uses. */
220	class FakeRedisClient {
221	  constructor() {
222	    this.store = new Map();
223	    this.isReady = true;
224	    this.failNext = false;
225	  }
226	
227	  on() {
228	    return this;
229	  }
230	
231	  async connect() {
232	    this.isReady = true;
233	    return this;
234	  }
235	
236	  async quit() {
237	    this.isReady = false;
238	  }
239	
240	  async get(key) {
241	    if (this.failNext) {
242	      this.failNext = false;
243	      throw new Error('redis unavailable');
244	    }
245	    return this.store.has(key) ? this.store.get(key) : null;
246	  }
247	
248	  async set(key, value) {
249	    this.store.set(key, value);
250	    return 'OK';
251	  }
252	
253	  async del(key) {
254	    return this.store.delete(key) ? 1 : 0;
255	  }
256	
257	  /** Test helper: force the next get() to throw, simulating an outage. */
258	  simulateOutage() {
259	    this.failNext = true;
260	  }
261	
262	  seed(key, value) {
263	    this.store.set(key, JSON.stringify(value));
264	  }
265	}
266	
267	/** Cache wrapper matching createCacheAside's surface. */
268	function createFakeCache(redis) {
269	  const client = redis || new FakeRedisClient();
270	  return {
271	    client,
272	    async get(k) {
273	      const raw = await client.get(k);
274	      return raw ? JSON.parse(raw) : null;
275	    },
276	    async set(k, v) {
277	      await client.set(k, JSON.stringify(v));
278	      return true;
279	    },
280	    async del(k) {
281	      await client.del(k);
282	      return true;
283	    },
284	    async remember(k, loader) {
285	      const cached = await this.get(k);
286	      if (cached !== null) return cached;
287	      const fresh = await loader();
288	      if (fresh !== null && fresh !== undefined) await this.set(k, fresh);
289	      return fresh;
290	    },
291	  };
292	}
293	
294	/** RabbitMQ stand-in that records published events. */
295	function createFakeMessaging() {
296	  const published = [];
297	  return {
298	    published,
299	    async publish(routingKey, payload) {
300	      published.push({ routingKey, payload });
301	      return true;
302	    },
303	    async subscribe() {
304	      return true;
305	    },
306	    async close() {},
307	    isConnected() {
308	      return true;
309	    },
310	    /** Test helper: find published events by routing key. */
311	    events(routingKey) {
312	      return published.filter((p) => p.routingKey === routingKey);
313	    },
314	  };
315	}
316	
317	/** Elasticsearch stand-in. */
318	function createFakeSearch() {
319	  const docs = new Map();
320	  const indexName = 'test-questions';
321	  return {
322	    indexName,
323	    indexed: docs,
324	    async ping() {
325	      return true;
326	    },
327	    async ensureIndex(mappings) {
328	      this.mappings = mappings;
329	      return true;
330	    },
331	    async indexDocument(id, doc) {
332	      docs.set(String(id), doc);
333	      return true;
334	    },
335	    async search(query) {
336	      const q = String(query).toLowerCase();
337	      return [...docs.values()].filter((d) => (d.prompt || '').toLowerCase().includes(q));
338	    },
339	    async delete(id) {
340	      return docs.delete(String(id));
341	    },
342	  };
343	}
344	
345	/**
346	 * QuestionComponentClient stand-in. Either serve fixed questions, or throw to
347	 * exercise GameComponent's offline fallback path.
348	 */
349	function createFakeQuestionClient({ questions = null, healthy = true, throwOnList = false, throwOnCheck = false } = {}) {
350	  const bank = questions || [];
351	  return {
352	    async listQuestions() {
353	      if (throwOnList) throw new Error('question component unreachable');
354	      return bank;
355	    },
356	    async getPrompt(questionId) {
357	      const q = bank.find((x) => String(x.id) === String(questionId));
358	      if (!q) {
359	        const err = new Error('not found');
360	        err.status = 404;
361	        throw err;
362	      }
363	      return q;
364	    },
365	    async checkAnswer(questionId, answer) {
366	      if (throwOnCheck) throw new Error('question component unreachable');
367	      const q = bank.find((x) => String(x.id) === String(questionId));
368	      if (!q) {
369	        const err = new Error('not found');
370	        err.status = 404;
371	        throw err;
372	      }
373	      return { questionId, correct: String(answer) === String(q.correctOption) };
374	    },
375	    async health() {
376	      return healthy;
377	    },
378	  };
379	}
380	
381	module.exports = {
382	  FakePgPool,
383	  FakeRedisClient,
384	  createFakeCache,
385	  createFakeMessaging,
386	  createFakeSearch,
387	  createFakeQuestionClient,
388	};

  1	'use strict';
  2	
  3	/**
  4	 * QuestionComponent - the component named in the ComponentDiagram (spec.json
  5	 * view 9) and in the traceability matrix for ASR-1 (data durability).
  6	 *
  7	 *   artifact QuestionComponent
  8	 *   GameComponent -- QuestionComponent
  9	 *
 10	 * Responsibilities (spec section C/D): "question management and data
 11	 * persistence. [QuestionComponent owns question data.]"
 12	 *
 13	 * Stack (spec section D, recommended defaults): Node.js 18, Express.js 4,
 14	 * PostgreSQL 14, Redis 6, RabbitMQ 3, Elasticsearch 7, OAuth2, Prometheus 2,
 15	 * Docker 20.
 16	 *
 17	 * ASR-1 mitigation, straight from section D/E:
 18	 *   - "Use PostgreSQL for data persistence"
 19	 *   - "Implement data replication for high availability"
 20	 *   - "Use PostgreSQL replication for high availability"
 21	 *   - "Implement regular backups and data replication"
 22	 */
 23	const shared = require('@spacefractions/shared');
 24	const { config } = shared;
 25	
 26	const { QuestionService } = require('./service/questionService');
 27	const { QuestionRepository } = require('./repository/questionRepository');
 28	const { createQuestionRoutes } = require('./routes/questionRoutes');
 29	
 30	const ELASTIC_INDEX = process.env.QUESTION_INDEX || 'spacefractions-questions';
 31	
 32	class QuestionComponent {
 33	  constructor(options = {}) {
 34	    this.name = 'QuestionComponent';
 35	    this.config = config;
 36	    this.logger = options.logger || shared.createLogger(this.name);
 37	    this.metrics = options.metrics || shared.observability.createMetrics(this.name);
 38	
 39	    this.pool = options.pool || shared.postgres.createPool(this.logger, {
 40	      schema: config.schemas.question,
 41	    });
 42	
 43	    this.redis = options.redis || shared.redis.createRedisClient(this.logger);
 44	    this.cache = options.cache || shared.redis.createCacheAside(this.redis, this.logger, {
 45	      prefix: 'spacefractions:question',
 46	      ttlSeconds: config.redis.questionCacheTtlSeconds,
 47	    });
 48	
 49	    this.messaging = options.messaging || shared.messaging.createMessaging(this.logger, {
 50	      component: this.name,
 51	    });
 52	
 53	    this.search = options.search || shared.search.createSearchClient(this.logger, ELASTIC_INDEX);
 54	
 55	    this.repository = options.repository || new QuestionRepository({
 56	      pool: this.pool,
 57	      cache: this.cache,
 58	      search: this.search,
 59	      logger: this.logger,
 60	      schema: config.schemas.question,
 61	      metrics: this.metrics,
 62	    });
 63	
 64	    this.service = options.service || new QuestionService({
 65	      repository: this.repository,
 66	      messaging: this.messaging,
 67	      metrics: this.metrics,
 68	      logger: this.logger,
 69	      config,
 70	    });
 71	
 72	    this.app = this.buildApp();
 73	  }
 74	
 75	  buildApp() {
 76	    const app = shared.http.createApp({
 77	      componentName: this.name,
 78	      logger: this.logger,
 79	      metrics: this.metrics,
 80	      readyChecks: [
 81	        // ASR-1: PostgreSQL is the durable store, so it gates readiness.
 82	        { name: 'postgres', check: () => shared.postgres.ping(this.pool), required: true },
 83	        { name: 'redis', check: () => this.redis.isReady, required: false },
 84	        { name: 'rabbitmq', check: () => this.messaging.isConnected(), required: false },
 85	        { name: 'elasticsearch', check: () => this.search.ping(), required: false },
 86	      ],
 87	    });
 88	
 89	    app.use(createQuestionRoutes({ service: this.service, logger: this.logger }));
 90	
 91	    // Section G: "Create a runbook for common issues and errors." The seed /
