 30	  async register({ username, password, role = oauth2.ROLES.STUDENT, email = null, displayName = null }) {
 31	    if (!username || String(username).trim().length < 3) {
 32	      throw httpError(400, 'invalid_request', 'username must be at least 3 characters');
 33	    }
 34	    if (!Object.values(oauth2.ROLES).includes(role)) {
 35	      throw httpError(400, 'invalid_request', `role must be one of ${Object.values(oauth2.ROLES).join(', ')}`);
 36	    }
 37	    const existing = await this.repository.findByUsername(username);
 38	    if (existing) {
 39	      throw httpError(409, 'user_exists', `username ${username} is already taken`);
 40	    }
 41	
 42	    const user = role === oauth2.ROLES.ADMIN
 43	      ? new Admin({ username, email, displayName })
 44	      : new User({ username, role, email, displayName });
 45	    user.setPassword(password);
