 51	  /** OAuth2 password grant. */
 52	  async authenticate({ username, password, scope = null }) {
 53	    const user = await this.repository.findByUsername(username);
 54	
 55	    // Always run a hash comparison so a missing user and a wrong password take
 56	    // comparable time (avoids username enumeration).
 57	    const dummy = new User({ username: '__nonexistent__' });
 58	    dummy.setPassword('placeholder-not-a-real-password');
 59	    const ok = user ? user.verifyPassword(password) : (dummy.verifyPassword(password), false);
 60	
 61	    if (!user || !ok) {
 62	      throw httpError(401, 'invalid_grant', 'Invalid username or password');
 63	    }
 64	    if (!user.active) {
 65	      throw httpError(403, 'account_disabled', 'This account has been disabled');
 66	    }
 67	
 68	    const grantedScopes = scope ? String(scope).split(' ').filter(Boolean) : user.scopes;
 69	    const token = this.issueToken(user, grantedScopes);
 70	    const refreshToken = await this.issueRefreshToken(user);
 71	
 72	    if (this.messaging) {
 73	      await this.messaging.publish(this.config.rabbitmq.events.userAuthenticated, {
 74	        userId: user.id,
 75	        username: user.username,
 76	        role: user.role,
 77	        grantType: 'password',
 78	      });
 79	    }
 80	
 81	    return {
 82	      access_token: token,
 83	      token_type: 'Bearer',
 84	      expires_in: 3600,
 85	      refresh_token: refreshToken,
 86	      scope: grantedScopes.join(' '),
 87	      user: user.toJSON(),
 88	    };
 89	  }
