 91	  /** OAuth2 client_credentials grant for service-to-service calls. */
 92	  issueServiceToken({ clientId, clientSecret, scope = null }) {
 93	    const expectedId = process.env.SERVICE_CLIENT_ID || 'spacefractions-internal';
 94	    const expectedSecret = process.env.SERVICE_CLIENT_SECRET || 'internal-secret-change-me';
 95	
 96	    const idOk = safeEquals(clientId || '', expectedId);
 97	    const secretOk = safeEquals(clientSecret || '', expectedSecret);
 98	    if (!idOk || !secretOk) {
 99	      throw httpError(401, 'invalid_client', 'Invalid client credentials');
100	    }
101	
102	    const grantedScopes = scope ? String(scope).split(' ').filter(Boolean) : Object.values(oauth2.SCOPES);
103	    const now = Math.floor(Date.now() / 1000);
104	    const token = oauth2.signToken(
105	      {
106	        sub: 'service:spacefractions-internal',
107	        username: expectedId,
108	        role: oauth2.ROLES.ADMIN,
109	        roles: [oauth2.ROLES.ADMIN],
110	        scope: grantedScopes.join(' '),
111	        iat: now,
112	        client_id: expectedId,
113	      },
114	      '1h',
115	    );
116	    return {
117	      access_token: token,
118	      token_type: 'Bearer',
119	      expires_in: 3600,
120	      scope: grantedScopes.join(' '),
121	    };
122	  }
