124	  issueToken(user, scopes) {
125	    const now = Math.floor(Date.now() / 1000);
126	    return oauth2.signToken({
127	      sub: user.id,
128	      username: user.username,
129	      role: user.role,
130	      roles: [user.role],
131	      scope: scopes.join(' '),
132	      iat: now,
133	    });
134	  }
