  5	/**
  6	 * Game - the class named in the ClassDiagram (spec.json view 2):
  7	 *
  8	 *   class Game {
  9	 *     - id: string
 10	 *     - score: int
 11	 *     + play(): void
 12	 *     + viewScore(): int
 13	 *   }
 14	 *
 15	 * The StateDiagram (spec.json view 4) drives the transition table:
 16	 *   [*] --> Playing
 17	 *   Playing --> Paused   : pause()
 18	 *   Paused  --> Playing  : resume()
 19	 *   Playing --> GameOver : gameOver()
 20	 *
 21	 * Game --* Question (composition) from the class diagram: a game owns the
 22	 * ordered list of questions it will serve, so scoring is deterministic.
 23	 */
 24	class Game {
 25	  /**
 26	   * @param {object} props
 27	   * @param {string} [props.id]
 28	   * @param {number} [props.score]
 29	   * @param {string} [props.state]
 30	   * @param {object} [props.user]
 31	   * @param {Array<{id:string,prompt:string,options:string[],correctOption:string}>} [props.questions]
 32	   */
 33	  constructor(props = {}) {
 34	    this.id = props.id || newId();
 35	    this.score = Number.isInteger(props.score) ? props.score : 0;
 36	    this.state = ALL_GAME_STATES.includes(props.state) ? props.state : GAME_STATES.PLAYING;
 37	    this.user = props.user || null;
 38	    // Game --* Question : composition, so questions are owned values here.
 39	    this.questions = Array.isArray(props.questions) ? props.questions : [];
 40	    this.answers = Array.isArray(props.answers) ? props.answers : [];
 41	    this.currentIndex = Number.isInteger(props.currentIndex) ? props.currentIndex : 0;
 42	    this.startedAt = props.startedAt || new Date().toISOString();
 43	    this.endedAt = props.endedAt || null;
 44	    this.updatedAt = new Date().toISOString();
 45	  }
 46	
 47	  /** ClassDiagram: + play(): void - transitions the game into Playing. */
 48	  play() {
 49	    if (this.state === GAME_STATES.GAME_OVER) {
 50	      const err = new Error('Cannot play a game that is already over');
 51	      err.status = 409;
 52	      err.code = 'game_already_over';
 53	      throw err;
 54	    }
 55	    this.state = GAME_STATES.PLAYING;
 56	    this.touch();
 57	    return this.state;
 58	  }
 59	
 60	  /** StateDiagram: pause() */
 61	  pause() {
 62	    if (this.state !== GAME_STATES.PLAYING) {
 63	      return this.badTransition(GAME_STATES.PAUSED);
 64	    }
 65	    this.state = GAME_STATES.PAUSED;
 66	    this.touch();
 67	    return this.state;
 68	  }
 69	
 70	  /** StateDiagram: resume() */
 71	  resume() {
 72	    if (this.state !== GAME_STATES.PAUSED) {
 73	      return this.badTransition(GAME_STATES.PLAYING);
 74	    }
 75	    this.state = GAME_STATES.PLAYING;
 76	    this.touch();
 77	    return this.state;
 78	  }
