112	  }
113	
114	  get totalQuestions() {
115	    return this.questions.length;
116	  }
117	
118	  /**
119	   * Record an answer. Scoring rule chosen by us (the spec names a score but
120	   * never defines the formula - see README):
121	   *   correct answer   -> +10 * difficultyWeight (default 1) points
122	   *   incorrect answer -> no points, no penalty (it is a learning tool)
123	   * The game ends automatically once every question is answered.
124	   */
125	  submitAnswer({ questionId, answer, timeMs = null }) {
126	    if (this.state === GAME_STATES.GAME_OVER) {
127	      const err = new Error('Cannot submit an answer to a finished game');
128	      err.status = 409;
129	      err.code = 'game_already_over';
130	      throw err;
131	    }
132	    if (this.state === GAME_STATES.PAUSED) {
133	      const err = new Error('Game is paused; resume before answering');
134	      err.status = 409;
135	      err.code = 'game_paused';
136	      throw err;
137	    }
138	
139	    const index = this.questions.findIndex((q) => q.id === questionId);
140	    if (index === -1) {
141	      const err = new Error(`Question ${questionId} is not part of game ${this.id}`);
