144	      throw err;
145	    }
146	    if (this.answers.some((a) => a.questionId === questionId)) {
147	      const err = new Error(`Question ${questionId} has already been answered in this game`);
148	      err.status = 409;
149	      err.code = 'question_already_answered';
150	      throw err;
151	    }
152	
153	    const question = this.questions[index];
154	    const correct = String(answer).trim() === String(question.correctOption).trim();
155	    const weight = Number.isFinite(question.weight) ? question.weight : 1;
156	    const awarded = correct ? 10 * weight : 0;
157	
158	    this.score += awarded;
159	    this.answers.push({
160	      questionId,
161	      answer,
162	      correct,
163	      awarded,
164	      timeMs: Number.isFinite(timeMs) ? timeMs : null,
165	      answeredAt: new Date().toISOString(),
166	    });
167	
168	    if (this.answers.length >= this.questions.length && this.questions.length > 0) {
169	      this.gameOver();
170	    }
171	
172	    this.touch();
173	    return { correct, awarded, correctOption: question.correctOption, score: this.score };
174	  }
