176	  /** ClassDiagram: User + viewScore(game: Game): int -> feedback block. */
177	  feedback() {
178	    const total = this.questions.length;
179	    const correct = this.answers.filter((a) => a.correct).length;
180	    return {
181	      gameId: this.id,
182	      score: this.score,
183	      state: this.state,
184	      answered: this.answers.length,
185	      totalQuestions: total,
186	      correctAnswers: correct,
187	      accuracy: total === 0 ? 0 : correct / total,
188	      completed: this.isOver,
189	      message: this.completionMessage(correct, total),
190	    };
191	  }
192	
193	  completionMessage(correct, total) {
194	    if (total === 0) return 'No questions were available for this round.';
195	    const ratio = correct / total;
196	    if (ratio === 1) return 'Perfect! You are a fraction astronaut!';
197	    if (ratio >= 0.8) return 'Great work! You have a strong grasp of fractions.';
198	    if (ratio >= 0.5) return 'Good effort. Review the ones you missed and try again.';
199	    return 'Keep practising. Fractions take a few orbits to master!';
200	  }
201	
202	  /** Game state is what gets cached in Redis and persisted as JSONB. */
203	  toJSON() {
204	    return {
205	      id: this.id,
206	      score: this.score,
207	      state: this.state,
208	      user: this.user,
209	      questions: this.questions,
210	      answers: this.answers,
211	      currentIndex: this.currentIndex,
212	      startedAt: this.startedAt,
213	      endedAt: this.endedAt,
214	      updatedAt: this.updatedAt,
215	    };
216	  }
217	
218	  static fromJSON(json) {
219	    if (!json) return null;
220	    if (typeof json === 'string') return new Game(JSON.parse(json));
221	    return new Game(json);
222	  }
223	
224	  touch() {
225	    this.updatedAt = new Date().toISOString();
226	  }
227	}
228	
229	module.exports = { Game };

