  7	/**
  8	 * OAuth2 authentication / authorization (spec section D: "Authn/authz: OAuth2",
  9	 * section F: "Implement OAuth2 for authentication and authorization / Use
 10	 * secure password storage and transmission").
 11	 *
 12	 * Supports two verification modes:
 13	 *   1. JWKS (production, service mesh / real IdP): set OAUTH2_JWKS_URI.
 14	 *   2. HS256 shared secret (local dev + the UserComponent's own token issuer).
 15	 *
 16	 * The spec never names an identity provider or token endpoint, so the
 17	 * UserComponent issues its own OAuth2 client-credentials + password-grant style
 18	 * tokens. Documented in README -> "Underspecified areas".
 19	 */
 20	
 21	const ROLES = Object.freeze({
 22	  STUDENT: 'student',
 23	  TEACHER: 'teacher',
 24	  ADMIN: 'admin',
 25	});
 26	
 27	const SCOPES = Object.freeze({
 28	  PLAY_GAME: 'game:play',
 29	  VIEW_SCORE: 'game:score:read',
 30	  UPDATE_QUESTIONS: 'questions:write',
 31	  READ_QUESTIONS: 'questions:read',
 32	  VIEW_HELP: 'help:read',
 33	});
 34	
 35	const ROLE_SCOPES = Object.freeze({
 36	  [ROLES.STUDENT]: [SCOPES.PLAY_GAME, SCOPES.VIEW_SCORE, SCOPES.READ_QUESTIONS, SCOPES.VIEW_HELP],
 37	  [ROLES.TEACHER]: [SCOPES.READ_QUESTIONS, SCOPES.VIEW_SCORE, SCOPES.VIEW_HELP],
 38	  [ROLES.ADMIN]: Object.values(SCOPES),
 39	});
 40	
 41	function createJwksClient() {
 42	  if (!config.oauth2.jwksUri) return null;
 43	  return jwksRsa({
 44	    jwksUri: config.oauth2.jwksUri,
 45	    cache: true,
 46	    cacheMaxEntries: 10,
 47	    cacheMaxAge: 10 * 60 * 1000,
 48	    rateLimit: true,
 49	    jwksRequestsPerMinute: 10,
 50	  });
 51	}
 52	
 53	const jwksClient = createJwksClient();
 54	
 55	function getKey(header, callback) {
 56	  if (jwksClient) {
 57	    jwksClient.getSigningKey(header.kid, (err, key) => {
 58	      if (err) return callback(err);
 59	      return callback(null, key.getPublicKey());
 60	    });
 61	    return;
 62	  }
 63	  callback(null, config.oauth2.secret);
 64	}
 65	
 66	/**
 67	 * Verify a bearer token. Returns the decoded claims or throws.
 68	 */
 69	function verifyToken(token) {
 70	  return new Promise((resolve, reject) => {
 71	    jwt.verify(
 72	      token,
 73	      getKey,
 74	      {
 75	        algorithms: config.oauth2.jwksUri ? ['RS256'] : ['HS256'],
 76	        audience: config.oauth2.audience,
 77	        issuer: config.oauth2.issuer,
 78	      },
 79	      (err, decoded) => (err ? reject(err) : resolve(decoded)),
 80	    );
 81	  });
 82	}
 83	
 84	function signToken(claims, expiresIn = '1h') {
 85	  return jwt.sign(claims, config.oauth2.secret, {
 86	    algorithm: 'HS256',
 87	    expiresIn,
 88	    issuer: config.oauth2.issuer,
 89	    audience: config.oauth2.audience,
 90	  });
 91	}
