 93	/**
 94	 * Express middleware factory.
 95	 *
 96	 * @param {object} opts
 97	 * @param {string[]} [opts.scopes]  scopes required to reach the route
 98	 * @param {string[]} [opts.roles]   roles required in addition to scopes
 99	 * @param {boolean} [opts.optional] when true, an absent token is allowed
100	 */
101	function authenticate(opts = {}) {
102	  const requiredScopes = opts.scopes || [];
103	  const requiredRoles = opts.roles || [];
104	  const optional = Boolean(opts.optional);
105	
106	  return async function authMiddleware(req, res, next) {
107	    const header = req.headers.authorization || '';
108	    const [scheme, token] = header.split(' ');
109	
110	    if (!token || scheme.toLowerCase() !== 'bearer') {
111	      if (optional) {
112	        req.user = null;
113	        return next();
114	      }
115	      return res.status(401).json({
116	        error: 'unauthorized',
117	        error_description: 'Missing OAuth2 bearer token',
118	      });
119	    }
120	
121	    let claims;
122	    try {
123	      claims = await verifyToken(token);
124	    } catch (err) {
125	      return res.status(401).json({
126	        error: 'invalid_token',
127	        error_description: err.message,
128	      });
129	    }
130	
131	    const grantedScopes = String(claims.scope || '').split(/\s+/).filter(Boolean);
132	    const grantedRoles = Array.isArray(claims.roles) ? claims.roles : [claims.role].filter(Boolean);
133	
134	    const missingScopes = requiredScopes.filter((s) => !grantedScopes.includes(s) && !grantedScopes.includes('*'));
135	    if (missingScopes.length > 0) {
136	      return res.status(403).json({
137	        error: 'insufficient_scope',
138	        error_description: `Missing scope(s): ${missingScopes.join(', ')}`,
139	      });
140	    }
141	
142	    const missingRoles = requiredRoles.filter((r) => !grantedRoles.includes(r));
143	    if (missingRoles.length > 0) {
144	      return res.status(403).json({
145	        error: 'insufficient_role',
146	        error_description: `Missing role(s): ${missingRoles.join(', ')}`,
147	      });
148	    }
149	
150	    req.user = {
151	      id: claims.sub,
152	      username: claims.username || claims.preferred_username,
153	      roles: grantedRoles,
154	      scopes: grantedScopes,
155	      claims,
156	    };
157	    return next();
158	  };
159	}
160	
161	function scopesForRole(role) {
162	  return ROLE_SCOPES[role] || [];
163	}
164	
165	module.exports = {
166	  ROLES,
167	  SCOPES,
168	  ROLE_SCOPES,
169	  authenticate,
170	  verifyToken,
171	  signToken,
172	  scopesForRole,
173	};

