  5	/**
  6	 * QuestionRepository - PostgreSQL persistence for question data.
  7	 *
  8	 * This is the component that must satisfy ASR-1 "Data durability: ensures that
  9	 * question data is persisted and recoverable". Section D/E name the mechanisms:
 10	 *   - "Use PostgreSQL replication for high availability"
 11	 *   - "Implement regular backups and data replication"
 12	 *
 13	 * Schema is in sql/question_ddl.sql (the DDL referenced by ASR-1 in the
 14	 * traceability matrix). Redis is a read cache only; Elasticsearch is a
 15	 * rebuildable search index. PostgreSQL holds the truth.
 16	 */
 17	class QuestionRepository {
 18	  constructor({ pool, cache, search, logger, schema = 'question', metrics = null }) {
 19	    this.pool = pool;
 20	    this.cache = cache;
 21	    this.search = search;
 22	    this.logger = logger;
 23	    this.schema = schema;
 24	    this.metrics = metrics;
 25	  }
 26	
 27	  get table() {
 28	    return `${this.schema}.questions`;
 29	  }
 30	
 31	  async insert(question) {
 32	    const sql = `
 33	      INSERT INTO ${this.table}
 34	        (question_uid, prompt, options, correct_option, difficulty, weight, tags, active)
 35	      VALUES ($1, $2, $3::jsonb, $4, $5, $6, $7::jsonb, $8)
 36	      RETURNING id, question_uid, created_at, updated_at, version
 37	    `;
 38	    const params = [
 39	      question.id,
 40	      question.prompt,
 41	      JSON.stringify(question.options),
 42	      question.correctOption,
 43	      question.difficulty,
 44	      question.weight,
 45	      JSON.stringify(question.tags),
 46	      question.active,
 47	    ];
 48	    const op = () => this.pool.query(sql, params);
 49	    const { rows } = this.metrics
 50	      ? await this.metrics.timeExternal('postgres', 'insertQuestion', op)
 51	      : await op();
 52	    await this.invalidate(question.id);
 53	    if (this.search) {
 54	      await this.search.indexDocument(question.id, searchDoc(question));
 55	    }
 56	    return rows[0];
 57	  }
 58	
 59	  async update(questionId, patch) {
 60	    const existing = await this.findById(questionId, { bypassCache: true });
 61	    if (!existing) return null;
 62	
 63	    const merged = Question.fromJSON({ ...existing.toJSON(), ...patch, id: questionId });
 64	    const validation = merged.validate();
 65	    if (!validation.valid) {
 66	      const err = new Error(validation.errors.join('; '));
 67	      err.status = 400;
 68	      err.code = 'invalid_question';
 69	      throw err;
 70	    }
 71	    merged.version = existing.version + 1;
 72	    merged.updatedAt = new Date().toISOString();
 73	
 74	    const sql = `
 75	      UPDATE ${this.table}
 76	         SET prompt = $2,
 77	             options = $3::jsonb,
 78	             correct_option = $4,
 79	             difficulty = $5,
 80	             weight = $6,
 81	             tags = $7::jsonb,
 82	             active = $8,
 83	             updated_at = NOW(),
 84	             version = version + 1
 85	       WHERE question_uid = $1
 86	      RETURNING id, question_uid, created_at, updated_at, version
 87	    `;
 88	    const params = [
 89	      questionId,
 90	      merged.prompt,
 91	      JSON.stringify(merged.options),
 92	      merged.correctOption,
 93	      merged.difficulty,
 94	      merged.weight,
 95	      JSON.stringify(merged.tags),
 96	      merged.active,
 97	    ];
 98	    const op = () => this.pool.query(sql, params);
 99	    const { rows } = this.metrics
100	      ? await this.metrics.timeExternal('postgres', 'updateQuestion', op)
101	      : await op();
102	
103	    await this.invalidate(questionId);
104	    if (this.search) await this.search.indexDocument(questionId, searchDoc(merged));
105	    return rows[0] || null;
106	  }
107	
108	  async findById(questionId, { bypassCache = false } = {}) {
109	    const cacheKey = `question:${questionId}`;
110	    if (!bypassCache && this.cache) {
111	      const cached = await this.cache.get(cacheKey);
112	      if (cached) return Question.fromJSON(cached);
113	    }
114	
115	    const op = () => this.pool.query(
116	      `SELECT * FROM ${this.table} WHERE question_uid = $1 AND active = TRUE`,
117	      [questionId],
118	    );
119	    const { rows } = this.metrics
120	      ? await this.metrics.timeExternal('postgres', 'findQuestion', op)
121	      : await op();
122	    if (!rows[0]) return null;
123	
124	    const question = Question.fromJSON(rowToQuestion(rows[0]));
125	    if (this.cache) await this.cache.set(cacheKey, question.toJSON());
