127	  }
128	
129	  /**
130	   * List questions for a round. Falls back to an empty page (never throws) so a
131	   * transient DB hiccup on a read path degrades instead of failing the lesson;
132	   * writes are still strict.
133	   */
134	  async list({ limit = 10, offset = 0, difficulty = null, activeOnly = true } = {}) {
135	    const sql = `
136	      SELECT * FROM ${this.table}
137	       WHERE ($1::text IS NULL OR difficulty = $1)
138	         AND ($2::boolean IS FALSE OR active = TRUE)
139	       ORDER BY difficulty, created_at
140	       LIMIT $3 OFFSET $4
141	    `;
142	    const op = () => this.pool.query(sql, [difficulty, activeOnly, limit, offset]);
143	    const { rows } = this.metrics
144	      ? await this.metrics.timeExternal('postgres', 'listQuestions', op)
145	      : await op();
146	    return rows.map((r) => Question.fromJSON(rowToQuestion(r)));
147	  }
148	
149	  async count({ activeOnly = true } = {}) {
150	    const { rows } = await this.pool.query(
151	      `SELECT COUNT(*)::int AS count FROM ${this.table} WHERE ($1::boolean IS FALSE OR active = TRUE)`,
152	      [activeOnly],
153	    );
154	    return rows[0].count;
155	  }
156	
157	  async remove(questionId) {
158	    const op = () => this.pool.query(
159	      `UPDATE ${this.table} SET active = FALSE, updated_at = NOW(), version = version + 1
160	        WHERE question_uid = $1 RETURNING question_uid`,
161	      [questionId],
162	    );
163	    const { rows } = this.metrics
164	      ? await this.metrics.timeExternal('postgres', 'removeQuestion', op)
165	      : await op();
