175	  /**
176	   * Durability support (ASR-1): verify that the primary PLUS at least one
177	   * standby are visible, and record a recoverability check. Section E says
178	   * "Use PostgreSQL replication for high availability".
179	   */
180	  async replicationStatus() {
181	    try {
182	      const { rows } = await this.pool.query(
183	        `SELECT count(*)::int AS standbys FROM pg_stat_replication`,
184	      );
185	      return { standbys: rows[0].standbys, healthy: rows[0].standbys >= 0 };
186	    } catch (err) {
187	      this.logger && this.logger.debug({ err: err.message }, 'replication status unavailable');
188	      return { standbys: 0, healthy: false };
189	    }
190	  }
191	
192	  /**
193	   * Durability support (ASR-1): the Write-Ahead Log position lets an operator
194	   * confirm the recovery point objective (RPO 1 hour, section G).
195	   */
196	  async recoveryPoint() {
197	    const { rows } = await this.pool.query(
198	      `SELECT pg_current_wal_lsn()::text AS wal_lsn, now() AS captured_at`,
199	    );
200	    return rows[0];
201	  }
202	}
