204	/** Row -> domain object mapping (JSONB columns come back parsed by pg). */
205	function rowToQuestion(row) {
206	  return {
207	    id: row.question_uid,
208	    prompt: row.prompt,
209	    options: typeof row.options === 'string' ? JSON.parse(row.options) : row.options,
210	    correctOption: row.correct_option,
211	    difficulty: row.difficulty,
212	    weight: Number(row.weight),
213	    tags: typeof row.tags === 'string' ? JSON.parse(row.tags) : row.tags,
214	    active: row.active,
215	    createdAt: row.created_at ? new Date(row.created_at).toISOString() : undefined,
216	    updatedAt: row.updated_at ? new Date(row.updated_at).toISOString() : undefined,
217	    version: row.version,
218	  };
219	}
220	
221	function searchDoc(question) {
222	  return {
223	    id: question.id,
224	    prompt: question.prompt,
225	    options: question.options,
226	    correctOption: question.correctOption,
227	    difficulty: question.difficulty,
228	    tags: question.tags,
229	  };
230	}
