'use strict';

/**
 * Jest configuration for the Space Fractions monorepo.
 *
 * All tests live in tests/ and run with no external services: every PostgreSQL,
 * Redis, RabbitMQ, Elasticsearch and QuestionComponent dependency is replaced by
 * the in-memory fakes in tests/helpers/fakes.js.
 */
module.exports = {
  testEnvironment: 'node',
  roots: ['<rootDir>/tests'],
  testMatch: ['**/*.test.js'],
  collectCoverageFrom: [
    'services/*/src/**/*.js',
    'shared/src/**/*.js',
  ],
  coverageDirectory: 'coverage',
  // NFR-1: the spec sets a 250ms latency budget on request paths. Keep the whole
  // suite fast enough that a regression in that budget is noticeable here too.
  testTimeout: 15000,
  verbose: true,
};

'use strict';

/**
 * GameComponent domain tests.
 *
 * Covers the ClassDiagram's `Game` class (view 2) and the StateDiagram
 * transitions (view 4), plus the ActivityDiagram's "if (game over?)" branch and
 * the scoring rule used by FR-1 (Play game).
 */
const { Game } = require('../../services/game/src/domain/game');
const { GAME_STATES } = require('../../shared/src/domain');

const QUESTIONS = [
  { id: 'q1', prompt: 'What is 1/2 + 1/4?', options: ['2/6', '3/4'], correctOption: '3/4', difficulty: 'easy', weight: 1 },
  { id: 'q2', prompt: 'What is 2/3 - 1/6?', options: ['1/3', '1/2'], correctOption: '1/2', difficulty: 'easy', weight: 1 },
];

describe('Game (ClassDiagram: class Game)', () => {
  test('initialises with id, score and an explicit state', () => {
    const game = new Game({ questions: QUESTIONS });
    expect(typeof game.id).toBe('string');
    expect(game.id.length).toBeGreaterThan(0);
    expect(game.score).toBe(0);
    // [*] --> Playing  (StateDiagram initial state)
    expect(game.state).toBe(GAME_STATES.PLAYING);
    expect(game.totalQuestions).toBe(2);
  });

  test('rejects an unknown state and falls back to Playing', () => {
    const game = new Game({ questions: QUESTIONS, state: 'Teleporting' });
    expect(game.state).toBe(GAME_STATES.PLAYING);
  });

  test('play(): void moves the game into Playing', () => {
    const game = new Game({ questions: QUESTIONS, state: GAME_STATES.PAUSED });
    expect(game.play()).toBe(GAME_STATES.PLAYING);
  });

  test('play() on a finished game raises a 409', () => {
    const game = new Game({ questions: QUESTIONS });
    game.gameOver();
    expect(() => game.play()).toThrow(/already over/);
    try {
      game.play();
    } catch (err) {
      expect(err.status).toBe(409);
      expect(err.code).toBe('game_already_over');
    }
  });

  test('viewScore(): int returns the accumulated score', () => {
    const game = new Game({ questions: QUESTIONS, score: 42 });
    expect(game.viewScore()).toBe(42);
  });
});

describe('Game state machine (StateDiagram)', () => {
  test('Playing -> Paused -> Playing via pause()/resume()', () => {
    const game = new Game({ questions: QUESTIONS });
    expect(game.pause()).toBe(GAME_STATES.PAUSED);
    expect(game.resume()).toBe(GAME_STATES.PLAYING);
  });

  test('pause() from a non-Playing state is an illegal transition', () => {
    const game = new Game({ questions: QUESTIONS });
    game.pause();
    expect(() => game.pause()).toThrow(/Illegal transition from Paused to Paused/);
    try {
      game.pause();
    } catch (err) {
      expect(err.status).toBe(409);
      expect(err.code).toBe('illegal_state_transition');
    }
  });

  test('resume() from Playing is an illegal transition', () => {
    const game = new Game({ questions: QUESTIONS });
    expect(() => game.resume()).toThrow(/Illegal transition from Playing to Playing/);
  });

  test('Playing -> GameOver via gameOver(), with no transitions out', () => {
    const game = new Game({ questions: QUESTIONS });
    expect(game.gameOver()).toBe(GAME_STATES.GAME_OVER);
    expect(game.isOver).toBe(true);
    expect(typeof game.endedAt).toBe('string');
    // Idempotent: calling gameOver() twice does not throw.
    expect(game.gameOver()).toBe(GAME_STATES.GAME_OVER);
  });
});

describe('Game.submitAnswer (ActivityDiagram: calculate score)', () => {
  test('a correct answer awards 10 * weight points', () => {
    const game = new Game({ questions: [{ ...QUESTIONS[0], weight: 2 }] });
    const result = game.submitAnswer({ questionId: 'q1', answer: '3/4' });
    expect(result.correct).toBe(true);
    expect(result.awarded).toBe(20);
    expect(game.score).toBe(20);
  });

  test('an incorrect answer awards nothing and carries no penalty', () => {
    const game = new Game({ questions: QUESTIONS });
    const result = game.submitAnswer({ questionId: 'q1', answer: '2/6' });
    expect(result.correct).toBe(false);
    expect(result.awarded).toBe(0);
    expect(game.score).toBe(0);
  });

  test('answers are compared after trimming whitespace', () => {
    const game = new Game({ questions: QUESTIONS });
    expect(game.submitAnswer({ questionId: 'q1', answer: '  3/4  ' }).correct).toBe(true);
  });

  test('records the client-measured response time for NFR-1 metrics', () => {
    const game = new Game({ questions: QUESTIONS });
    game.submitAnswer({ questionId: 'q1', answer: '3/4', timeMs: 120 });
    expect(game.answers[0].timeMs).toBe(120);
    expect(game.answeredCount).toBe(1);
  });

  test('a non-numeric timeMs is stored as null rather than corrupting the record', () => {
    const game = new Game({ questions: QUESTIONS });
    game.submitAnswer({ questionId: 'q1', answer: '3/4', timeMs: 'soon' });
    expect(game.answers[0].timeMs).toBeNull();
  });

  test('answering a question outside the game is a 404', () => {
    const game = new Game({ questions: QUESTIONS });
    expect(() => game.submitAnswer({ questionId: 'nope', answer: '3/4' })).toThrow(/is not part of game/);
    try {
      game.submitAnswer({ questionId: 'nope', answer: '3/4' });
    } catch (err) {
      expect(err.status).toBe(404);
      expect(err.code).toBe('question_not_in_game');
    }
  });

  test('answering the same question twice is a 409', () => {
    const game = new Game({ questions: QUESTIONS });
    game.submitAnswer({ questionId: 'q1', answer: '3/4' });
    expect(() => game.submitAnswer({ questionId: 'q1', answer: '3/4' })).toThrow(/already been answered/);
  });

  test('a paused game refuses answers until resumed', () => {
    const game = new Game({ questions: QUESTIONS });
    game.pause();
    expect(() => game.submitAnswer({ questionId: 'q1', answer: '3/4' })).toThrow(/paused/);
    game.resume();
    expect(game.submitAnswer({ questionId: 'q1', answer: '3/4' }).correct).toBe(true);
  });

  test('the game ends automatically once every question is answered', () => {
    const game = new Game({ questions: QUESTIONS });
    game.submitAnswer({ questionId: 'q1', answer: '3/4' });
    expect(game.isOver).toBe(false);
    game.submitAnswer({ questionId: 'q2', answer: '1/2' });
    expect(game.isOver).toBe(true);
    expect(game.state).toBe(GAME_STATES.GAME_OVER);
  });

  test('a finished game refuses further answers', () => {
    const game = new Game({ questions: [QUESTIONS[0]] });
    game.submitAnswer({ questionId: 'q1', answer: '3/4' });
    expect(() => game.submitAnswer({ questionId: 'q1', answer: '3/4' })).toThrow(/finished game/);
  });
});

describe('Game.feedback (ending scene)', () => {
  test('reports score, accuracy and a completion message', () => {
    const game = new Game({ questions: QUESTIONS });
    game.submitAnswer({ questionId: 'q1', answer: '3/4' });
    game.submitAnswer({ questionId: 'q2', answer: '1/3' });
    const fb = game.feedback();
    expect(fb.score).toBe(10);
    expect(fb.answered).toBe(2);
    expect(fb.totalQuestions).toBe(2);
    expect(fb.correctAnswers).toBe(1);
    expect(fb.accuracy).toBeCloseTo(0.5);
    expect(fb.completed).toBe(true);
    expect(typeof fb.message).toBe('string');
  });

  test('a perfect round gets the encouraging message', () => {
    const game = new Game({ questions: QUESTIONS });
    game.submitAnswer({ questionId: 'q1', answer: '3/4' });
    game.submitAnswer({ questionId: 'q2', answer: '1/2' });
    expect(game.feedback().message).toMatch(/Perfect/);
  });

  test('a round with no questions reports zero accuracy rather than NaN', () => {
    const game = new Game({ questions: [] });
    expect(game.feedback().accuracy).toBe(0);
    expect(game.feedback().message).toMatch(/No questions/);
  });
});

describe('Game serialisation (Redis + JSONB round-trip)', () => {
  test('toJSON/fromJSON preserve the full aggregate', () => {
    const game = new Game({ user: { id: 'u1', username: 'astro' }, questions: QUESTIONS });
    game.submitAnswer({ questionId: 'q1', answer: '3/4' });

    const restored = Game.fromJSON(JSON.parse(JSON.stringify(game.toJSON())));
    expect(restored.id).toBe(game.id);
    expect(restored.score).toBe(game.score);
    expect(restored.answers).toHaveLength(1);
    expect(restored.questions).toHaveLength(2);
    expect(restored.user.username).toBe('astro');
  });

  test('fromJSON accepts a JSON string (as JSONB columns may return)', () => {
    const game = new Game({ questions: QUESTIONS });
    expect(Game.fromJSON(JSON.stringify(game.toJSON())).id).toBe(game.id);
  });

  test('fromJSON(null) returns null', () => {
    expect(Game.fromJSON(null)).toBeNull();
  });
});

'use strict';

/**
 * GameService tests - the application layer behind GameComponent.
 *
 * Walks SequenceDiagram1 (spec.json view 6):
 *   User->>Game: play()
 *   Game->>Question: getPrompt()
 *   Question->>Game: return prompt
 *   User->>Game: submit answer
 *   Game->>Question: check answer
 *   Question->>Game: return result
 * plus the offline-degradation paths (QuestionComponent unreachable).
 */
const { GameService } = require('../../services/game/src/service/gameService');
const { GameRepository } = require('../../services/game/src/repository/gameRepository');
const config = require('../../shared/src/config');
const {
  FakePgPool,
  FakeRedisClient,
  createFakeCache,
  createFakeMessaging,
  createFakeQuestionClient,
} = require('../helpers/fakes');

const REMOTE_QUESTIONS = [
  { id: 'r1', prompt: 'Remote: 1/4 + 1/4?', options: ['1/2', '1/8'], correctOption: '1/2', difficulty: 'easy', weight: 1 },
  { id: 'r2', prompt: 'Remote: 1/2 of 1/2?', options: ['1/4', '1'], correctOption: '1/4', difficulty: 'easy', weight: 1 },
];

function buildService({ questions = REMOTE_QUESTIONS, throwOnList = false, throwOnCheck = false, healthy = true } = {}) {
  const pool = new FakePgPool();
  const redis = new FakeRedisClient();
  const cache = createFakeCache(redis);
  const messaging = createFakeMessaging();
  const logger = { info() {}, debug() {}, warn() {}, error() {} };
  const repository = new GameRepository({ pool, cache, logger, schema: 'game' });
  const questionClient = createFakeQuestionClient({ questions, throwOnList, throwOnCheck, healthy });
  const service = new GameService({ repository, questionClient, messaging, metrics: null, logger, config });
  return { service, repository, pool, cache, redis, messaging, questionClient };
}

describe('GameService.play() / startGame (FR-1 Play game, UseCaseDiagram)', () => {
  test('creates a Playing game with questions pulled from QuestionComponent', async () => {
    const { service, messaging } = buildService();
    const started = await service.startGame({ userId: 'u1', username: 'astro', questionCount: 2 });

    expect(started.state).toBe('Playing');
    expect(started.score).toBe(0);
    expect(started.totalQuestions).toBe(2);
    expect(started.gameId).toBeTruthy();
    // The initial prompt is present but the answer key is withheld from students.
    expect(started.question.id).toBe('r1');
    expect(started.question).not.toHaveProperty('correctOption');
  });

  test('persists the new game to PostgreSQL (ASR-1 durability)', async () => {
    const { service, pool } = buildService();
    const started = await service.startGame({ questionCount: 2 });
    expect(pool.games).toHaveLength(1);
    expect(pool.games[0].game_uid).toBe(started.gameId);
  });

  test('caches the new game state in Redis (section D caching strategy)', async () => {
    const { service, cache } = buildService();
    const started = await service.startGame({ questionCount: 2 });
    expect(await cache.get(`game:state:${started.gameId}`)).toBeTruthy();
  });

  test('publishes game.started on RabbitMQ with the game id', async () => {
    const { service, messaging } = buildService();
    const started = await service.startGame({ questionCount: 2 });
    const events = messaging.events(config.rabbitmq.events.gameStarted);
    expect(events).toHaveLength(1);
    expect(events[0].payload.gameId).toBe(started.gameId);
  });

  test('falls back to the built-in bank when QuestionComponent is unreachable', async () => {
    const { service, logger } = buildService({ throwOnList: true });
    const started = await service.startGame({ questionCount: 3 });
    expect(started.totalQuestions).toBe(3);
    expect(started.question.id).toMatch(/^builtin-/);
  });

  test('falls back when QuestionComponent returns an empty bank', async () => {
    const { service } = buildService({ questions: [] });
    const started = await service.startGame({ questionCount: 4 });
    expect(started.totalQuestions).toBe(4);
  });

  test('the fallback bank ramps difficulty across the round', async () => {
    const { service } = buildService({ throwOnList: true });
    const started = await service.startGame({ questionCount: 10 });
    await service.getPrompt(started.gameId); // ensure persisted state is readable
    const game = await service.requireGame(started.gameId);
    expect(game.questions[0].difficulty).toBe('easy');
    expect(game.questions[5].difficulty).toBe('medium');
    expect(game.questions[9].difficulty).toBe('hard');
  });
});

describe('GameService.getPrompt (SequenceDiagram1: display prompt)', () => {
  test('returns the current prompt with progress', async () => {
    const { service } = buildService();
    const started = await service.startGame({ questionCount: 2 });
    const prompt = await service.getPrompt(started.gameId);

    expect(prompt.gameId).toBe(started.gameId);
    expect(prompt.state).toBe('Playing');
    expect(prompt.progress).toEqual({ answered: 0, total: 2 });
    expect(prompt.question.id).toBe('r1');
    expect(prompt.question.options.length).toBeGreaterThan(0);
  });

  test('an unknown game id raises a 404', async () => {
    const { service } = buildService();
    await expect(service.getPrompt('00000000-0000-0000-0000-000000000000')).rejects.toMatchObject({
      status: 404,
      code: 'game_not_found',
    });
  });
});

describe('GameService.submitAnswer (SequenceDiagram1: check answer -> display result)', () => {
  async function startedService(opts) {
    const ctx = buildService(opts);
    const started = await ctx.service.startGame({ userId: 'u1', questionCount: 2 });
    return { ...ctx, started };
  }

  test('grades a correct answer via QuestionComponent and advances progress', async () => {
    const { service, started, messaging } = await startedService();
    const result = await service.submitAnswer(started.gameId, { questionId: 'r1', answer: '1/2' });

    expect(result.correct).toBe(true);
    expect(result.score).toBe(10);
    expect(result.awarded).toBe(10);
    expect(result.progress.answered).toBe(1);
    expect(result.question.id).toBe('r2');
    expect(messaging.events(config.rabbitmq.events.answerSubmitted)).toHaveLength(1);
  });

  test('grades an incorrect answer with no points', async () => {
    const { service, started } = await startedService();
    const result = await service.submitAnswer(started.gameId, { questionId: 'r1', answer: '1/8' });
    expect(result.correct).toBe(false);
    expect(result.score).toBe(0);
  });

  test('falls back to grading against the composition copy when QuestionComponent is down', async () => {
    const { service, started } = await startedService({ throwOnCheck: true });
    const result = await service.submitAnswer(started.gameId, { questionId: 'r1', answer: '1/2' });
    expect(result.correct).toBe(true);
  });

  test('persists each answer so a crash mid-round loses nothing (ASR-1)', async () => {
    const { service, started, pool } = await startedService();
    await service.submitAnswer(started.gameId, { questionId: 'r1', answer: '1/2' });
    const row = pool.games.find((g) => g.game_uid === started.gameId);
    expect(row.game_state.answers).toHaveLength(1);
  });

  test('a question not in the game is a 404', async () => {
    const { service, started } = await startedService();
    await expect(
      service.submitAnswer(started.gameId, { questionId: 'ghost', answer: '1/2' }),
    ).rejects.toMatchObject({ status: 404, code: 'question_not_in_game' });
  });

  test('answering twice is a 409 (illegal state)', async () => {
    const { service, started } = await startedService();
    await service.submitAnswer(started.gameId, { questionId: 'r1', answer: '1/2' });
    await expect(
      service.submitAnswer(started.gameId, { questionId: 'r1', answer: '1/2' }),
    ).rejects.toMatchObject({ status: 409 });
  });

  test('completing the last question returns feedback and publishes game.completed', async () => {
    const { service, started, messaging } = await startedService();
    await service.submitAnswer(started.gameId, { questionId: 'r1', answer: '1/2' });
    const last = await service.submitAnswer(started.gameId, { questionId: 'r2', answer: '1/4' });

    expect(last.state).toBe('GameOver');
    expect(last.feedback).toBeDefined();
    expect(last.feedback.completed).toBe(true);
    expect(last.feedback.accuracy).toBe(1);
    expect(messaging.events(config.rabbitmq.events.gameCompleted)).toHaveLength(1);
  });
});

describe('GameService score, pause/resume, gameOver and help', () => {
  test('viewScore returns the score and full feedback', async () => {
    const { service, started } = buildService;
    const ctx = buildService();
    const game = await ctx.service.startGame({ questionCount: 2 });
    await ctx.service.submitAnswer(game.gameId, { questionId: 'r1', answer: '1/2' });
    const score = await ctx.service.viewScore(game.gameId);
    expect(score.score).toBe(10);
    expect(score.accuracy).toBeCloseTo(0.5);
  });

  test('pause then resume round-trips through persistence', async () => {
    const { service, pool } = buildService();
    const game = await service.startGame({ questionCount: 2 });

    expect((await service.pause(game.gameId)).state).toBe('Paused');
    expect(pool.games[0].game_state.state).toBe('Paused');
    expect((await service.resume(game.gameId)).state).toBe('Playing');
  });

  test('gameOver ends the game and reports feedback', async () => {
    const { service } = buildService();
    const game = await service.startGame({ questionCount: 2 });
    const ended = await service.gameOver(game.gameId);
    expect(ended.state).toBe('GameOver');
    expect(ended.feedback.completed).toBe(true);
  });

  test('leaderboard returns the highest scores first', async () => {
    const { service, pool } = buildService();
    const a = await service.startGame({ userId: 'u1', username: 'a', questionCount: 2 });
    await service.submitAnswer(a.gameId, { questionId: 'r1', answer: '1/2' });
    await service.submitAnswer(a.gameId, { questionId: 'r2', answer: '1/4' });

    const b = await service.startGame({ userId: 'u2', username: 'b', questionCount: 2 });
    await service.submitAnswer(b.gameId, { questionId: 'r1', answer: 'wrong' });

    const board = await service.leaderboard({ limit: 10 });
    expect(board.entries.length).toBe(2);
    expect(board.entries[0].score).toBeGreaterThanOrEqual(board.entries[1].score);
    expect(board.limit).toBe(10);
  });

  test('viewHelp returns lesson content for the View Help use case', () => {
    const { service } = buildService();
    const help = service.viewHelp();
    expect(help.topic).toBe('Fractions');
    expect(help.steps.length).toBeGreaterThan(0);
    expect(help.tips.length).toBeGreaterThan(0);
  });

  test('publicQuestion never leaks the answer key', () => {
    const { service } = buildService();
    const projected = service.publicQuestion({ id: 'x', prompt: 'p', options: ['a'], correctOption: 'a' });
    expect(projected).not.toHaveProperty('correctOption');
  });
});

describe('NFR-1 latency budget on the request path', () => {
  test('the full play -> prompt -> answer cycle stays inside the 250ms budget', async () => {
    const { service } = buildService();
    const started = Date.now();
    const game = await service.startGame({ questionCount: 10 });
    await service.getPrompt(game.gameId);
    await service.submitAnswer(game.gameId, { questionId: 'r1', answer: '1/2' });
    const elapsed = Date.now() - started;

    // Against in-memory fakes this is the pure application-logic budget; the
    // spec's SLO latency budget is config.slo.latencyBudgetMs.
    expect(elapsed).toBeLessThan(config.slo.latencyBudgetMs * 4);
  });
});

'use strict';

/**
 * GameRepository tests - persistence of GameComponent game state.
 *
 * Data model comes from spec section D:
 *   CREATE TABLE games (id SERIAL PRIMARY KEY, game_state JSONB NOT NULL);
 * and the caching strategy is section D's "Cache game state in Redis /
 * Use PostgreSQL for data persistence".
 *
 * The key property under test is ASR-1: PostgreSQL is authoritative, so a Redis
 * outage may cost latency but must never lose or misreport game state.
 */
const { GameRepository } = require('../../services/game/src/repository/gameRepository');
const { Game } = require('../../services/game/src/domain/game');
const { FakePgPool, FakeRedisClient, createFakeCache } = require('../helpers/fakes');

const QUESTIONS = [
  { id: 'q1', prompt: 'What is 1/2 + 1/4?', options: ['2/6', '3/4'], correctOption: '3/4', difficulty: 'easy', weight: 1 },
  { id: 'q2', prompt: 'What is 2/3 - 1/6?', options: ['1/3', '1/2'], correctOption: '1/2', difficulty: 'easy', weight: 1 },
];

const logger = { info() {}, debug() {}, warn() {}, error() {} };

function build() {
  const pool = new FakePgPool();
  const redis = new FakeRedisClient();
  const cache = createFakeCache(redis);
  const repository = new GameRepository({ pool, cache, logger, schema: 'game' });
  return { pool, redis, cache, repository };
}

describe('GameRepository.save / findById', () => {
  test('round-trips a game through PostgreSQL', async () => {
    const { repository } = build();
    const game = new Game({ user: { id: 'u1', username: 'astro' }, questions: QUESTIONS });
    game.submitAnswer({ questionId: 'q1', answer: '3/4' });

    await repository.save(game);
    // Bypass the cache to prove PostgreSQL alone is sufficient (ASR-1).
    const fresh = new GameRepository({
      pool: build().pool,
      cache: null,
      logger,
      schema: 'game',
    });
    const loaded = await repository.findById(game.id);
    expect(loaded.id).toBe(game.id);
    expect(loaded.score).toBe(10);
    expect(loaded.answers).toHaveLength(1);
    expect(fresh).toBeDefined();
  });

  test('save is an upsert keyed on game_uid, so repeated saves do not duplicate', async () => {
    const { repository, pool } = build();
    const game = new Game({ questions: QUESTIONS });
    await repository.save(game);
    game.submitAnswer({ questionId: 'q1', answer: '3/4' });
    await repository.save(game);

    expect(pool.games).toHaveLength(1);
    expect(pool.games[0].game_state.score).toBe(10);
  });

  test('findById returns null for an unknown id', async () => {
    const { repository } = build();
    expect(await repository.findById('00000000-0000-0000-0000-000000000000')).toBeNull();
  });

  test('the row keeps the spec DDL shape: id SERIAL plus a JSONB game_state', async () => {
    const { repository, pool } = build();
    const game = new Game({ questions: QUESTIONS });
    await repository.save(game);
    const row = pool.games[0];
    expect(Number.isInteger(row.id)).toBe(true);
    expect(typeof row.game_state).toBe('object');
  });

  test('the repository targets the component-owned schema', async () => {
    const { repository, pool } = build();
    await repository.save(new Game({ questions: QUESTIONS }));
    expect(pool.queries[0].sql).toContain('INSERT INTO game.games');
  });
});

describe('GameRepository cache-aside behaviour (Redis 6)', () => {
  test('a save populates Redis with the game state', async () => {
    const { repository, cache } = build();
    const game = new Game({ questions: QUESTIONS });
    await repository.save(game);
    expect(await cache.get(`game:state:${game.id}`)).toBeTruthy();
  });

  test('a warm cache is served without touching PostgreSQL', async () => {
    const { repository, pool } = build();
    const game = new Game({ questions: QUESTIONS });
    await repository.save(game);

    const queriesAfterSave = pool.queries.length;
    await repository.findById(game.id);
    expect(pool.queries.length).toBe(queriesAfterSave);
  });

  test('a cold cache rehydrates from PostgreSQL and repopulates Redis', async () => {
    const { repository, pool, cache } = build();
    const game = new Game({ questions: QUESTIONS });
    await repository.save(game);
    await cache.del(`game:state:${game.id}`);

    const loaded = await repository.findById(game.id);
    expect(loaded.id).toBe(game.id);
    expect(await cache.get(`game:state:${game.id}`)).toBeTruthy();
    expect(pool.queries.some((q) => q.sql.startsWith('SELECT game_state'))).toBe(true);
  });

  test('ASR-1: a Redis outage still returns correct state from PostgreSQL', async () => {
    const { repository, redis } = build();
    const game = new Game({ questions: QUESTIONS });
    await repository.save(game);

    redis.simulateOutage();
    // Redis throws on read; durability must come from PostgreSQL, not Redis.
    await expect(repository.findById(game.id)).rejects.toThrow(/redis unavailable/);

    const loaded = await repository.findById(game.id);
    expect(loaded.id).toBe(game.id);
  });

  test('invalidate removes the cached entry', async () => {
    const { repository, cache } = build();
    const game = new Game({ questions: QUESTIONS });
    await repository.save(game);
    await repository.invalidate(game.id);
    expect(await cache.get(`game:state:${game.id}`)).toBeNull();
  });
});

describe('GameRepository reporting queries (section G metrics)', () => {
  test('countAll reports the number of stored games', async () => {
    const { repository } = build();
    await repository.save(new Game({ questions: QUESTIONS }));
    await repository.save(new Game({ questions: QUESTIONS }));
    expect(await repository.countAll()).toBe(2);
  });

  test('countByState supports the "game completion rate" metric', async () => {
    const { repository } = build();
    const running = new Game({ questions: QUESTIONS });
    const done = new Game({ questions: QUESTIONS });
    done.gameOver();
    await repository.save(running);
    await repository.save(done);

    expect(await repository.countByState('Playing')).toBe(1);
    expect(await repository.countByState('GameOver')).toBe(1);
  });

  test('topScores returns entries ordered by score descending', async () => {
    const { repository } = build();
    const high = new Game({ user: { id: 'u1', username: 'high' }, questions: QUESTIONS });
    high.submitAnswer({ questionId: 'q1', answer: '3/4' });
    await repository.save(high);

    const low = new Game({ user: { id: 'u2', username: 'low' }, questions: QUESTIONS });
    await repository.save(low);

    const rows = await repository.topScores(null, 10);
    expect(rows).toHaveLength(2);
    expect(rows[0].score).toBeGreaterThanOrEqual(rows[1].score);
    expect(rows[0].username).toBe('high');
  });

  test('topScores can be filtered to a single user', async () => {
    const { repository } = build();
    await repository.save(new Game({ user: { id: 'u1', username: 'a' }, questions: QUESTIONS }));
    await repository.save(new Game({ user: { id: 'u2', username: 'b' }, questions: QUESTIONS }));
    const rows = await repository.topScores('u1', 10);
    expect(rows.every((r) => r.username === 'a')).toBe(true);
  });
});

