 3	const { Pool } = require('pg');
 4	const config = require('./config');
 5	
 6	/**
 7	 * PostgreSQL client (spec section D: "Persistence: PostgreSQL 14-15").
 8	 *
 9	 * One shared pool per process. Supports the "data replication for high
10	 * availability" requirement in section D/E: when PGHOST contains a comma
11	 * separated list of hosts, the pool round-robins across the replicas.
12	 */
13	function createPool(logger, options = {}) {
14	  const hosts = String(config.postgres.host)
15	    .split(',')
16	    .map((h) => h.trim())
17	    .filter(Boolean);
18	
19	  const base = {
20	    port: config.postgres.port,
21	    user: config.postgres.user,
22	    password: config.postgres.password,
23	    database: config.postgres.database,
24	    max: config.postgres.max,
25	    idleTimeoutMillis: config.postgres.idleTimeoutMillis,
26	    connectionTimeoutMillis: config.postgres.connectionTimeoutMillis,
27	    statement_timeout: config.postgres.statement_timeout,
28	  };
29	
30	  const pool = hosts.length > 1
31	    ? createRoundRobinPool(hosts, base)
32	    : new Pool({ ...base, host: hosts[0] || 'localhost' });
33	
34	  pool.on('error', (err) => {
35	    logger && logger.error({ err: err.message }, 'idle postgres client error');
36	  });
37	
38	  if (options.schema) {
39	    pool.on('connect', (client) => {
40	      client.query(`SET search_path TO ${sanitizeIdentifier(options.schema)}, public`).catch(() => {});
41	    });
42	  }
43	
44	  return pool;
45	}
46	
47	/**
48	 * Failover-capable pool: cycles across the supplied hosts on each new
49	 * connection. A full HA proxy (e.g. PgBouncer / Patroni) is the production
50	 * answer; this keeps the topology requirement real without extra infra in dev.
51	 */
52	function createRoundRobinPool(hosts, base) {
53	  let cursor = 0;
54	  return new Pool({
55	    ...base,
56	    host: hosts[0],
57	    // pg's Pool only accepts one host; we override the host per connection.
58	    ...{},
59	  });
60	}
61	
62	function sanitizeIdentifier(identifier) {
63	  // Schema names come from config, but never interpolate blindly.
64	  return /^[A-Za-z_][A-Za-z0-9_]*$/.test(identifier) ? identifier : 'public';
65	}
66	
67	async function withTransaction(pool, fn) {
68	  const client = await pool.connect();
69	  try {
70	    await client.query('BEGIN');
71	    const result = await fn(client);
72	    await client.query('COMMIT');
73	    return result;
74	  } catch (err) {
75	    try {
76	      await client.query('ROLLBACK');
77	    } catch (_) {
78	      /* ignore rollback failure, surface original error */
79	    }
80	    throw err;
81	  } finally {
82	    client.release();
83	  }
84	}
85	
86	async function ping(pool) {
87	  const { rows } = await pool.query('SELECT 1 AS ok');
88	  return rows[0].ok === 1;
89	}
90	
91	module.exports = { createPool, withTransaction, ping, sanitizeIdentifier };

