'use strict';

/**
 * QuestionComponent tests.
 *
 * Covers:
 *   - `Question`, the ClassDiagram class (view 2): getPrompt(), getOptions()
 *   - SequenceDiagram1's "check answer" / "return result" (grading)
 *   - SequenceDiagram2's "Admin ->> Question: update()"
 *   - ASR-1 (data durability): question data is persisted and recoverable
 */
const { Question } = require('../../services/question/src/domain/question');
const { QuestionService } = require('../../services/question/src/service/questionService');
const { QuestionRepository } = require('../../services/question/src/repository/questionRepository');
const { buildDefaultQuestionSet } = require('../../services/question/src/service/seedQuestions');
const config = require('../../shared/src/config');
const {
  FakePgPool,
  FakeRedisClient,
  createFakeCache,
  createFakeMessaging,
  createFakeSearch,
} = require('../helpers/fakes');

const silentLogger = { info() {}, debug() {}, warn() {}, error() {} };

describe('Question (ClassDiagram: class Question)', () => {
  test('getPrompt() and getOptions() match the diagram signatures', () => {
    const q = new Question({ prompt: 'What is 1/2 + 1/4?', options: ['2/6', '3/4'], correctOption: '3/4' });
    expect(q.getPrompt()).toBe('What is 1/2 + 1/4?');
    expect(q.getOptions()).toEqual(['2/6', '3/4']);
    expect(typeof q.id).toBe('string');
  });

  test('getOptions() returns a copy, so callers cannot mutate the aggregate', () => {
    const q = new Question({ prompt: 'p?', options: ['a', 'b'], correctOption: 'a' });
    q.getOptions().push('c');
    expect(q.options).toEqual(['a', 'b']);
  });

  test('defaults difficulty to medium and weight to 1', () => {
    const q = new Question({ prompt: 'p?', options: ['a', 'b'], correctOption: 'a' });
    expect(q.difficulty).toBe('medium');
    expect(q.weight).toBe(1);
  });
});

describe('Question.checkAnswer (SequenceDiagram1: check answer -> return result)', () => {
  const q = new Question({ prompt: 'What is 1/2 + 1/4?', options: ['2/6', '3/4'], correctOption: '3/4' });

  test('an exact match is correct', () => {
    expect(q.checkAnswer('3/4')).toMatchObject({ correct: true, reason: 'exact_match' });
  });

  test('whitespace is ignored', () => {
    expect(q.checkAnswer('  3/4 ').correct).toBe(true);
  });

  test('an equivalent fraction is accepted (a learning tool must not mark maths wrong)', () => {
    const half = new Question({ prompt: 'Simplify 2/4', options: ['1/2', '2/4'], correctOption: '1/2' });
    expect(half.checkAnswer('2/4')).toMatchObject({ correct: true, reason: 'equivalent_fraction' });
  });

  test('a wrong answer returns the correct option for feedback', () => {
    expect(q.checkAnswer('2/6')).toMatchObject({ correct: false, reason: 'mismatch', correctOption: '3/4' });
  });

  test('a null/undefined answer is reported as empty rather than throwing', () => {
    expect(q.checkAnswer(null)).toMatchObject({ correct: false, reason: 'empty_answer' });
    expect(q.checkAnswer(undefined)).toMatchObject({ correct: false, reason: 'empty_answer' });
  });
});

describe('Question.validate (admin authoring rules)', () => {
  test('a well-formed question passes', () => {
    const q = new Question({ prompt: 'What is 1/2?', options: ['1/2', '1/3'], correctOption: '1/2' });
    expect(q.validate()).toEqual({ valid: true, errors: [] });
  });

  test('rejects a too-short prompt', () => {
    const q = new Question({ prompt: 'x', options: ['a', 'b'], correctOption: 'a' });
    expect(q.validate().errors).toContain('prompt must be a string of at least 3 characters');
  });

  test('rejects fewer than two options', () => {
    const q = new Question({ prompt: 'What is 1/2?', options: ['a'], correctOption: 'a' });
    expect(q.validate().errors.join()).toMatch(/at least 2 entries/);
  });

  test('rejects an answer key that is not one of the options', () => {
    const q = new Question({ prompt: 'What is 1/2?', options: ['a', 'b'], correctOption: 'z' });
    expect(q.validate().errors).toContain('correctOption must be one of the options');
  });

  test('rejects an unknown difficulty', () => {
    const q = new Question({ prompt: 'What is 1/2?', options: ['a', 'b'], correctOption: 'a', difficulty: 'impossible' });
    expect(q.validate().errors.join()).toMatch(/easy, medium, hard/);
  });
});

describe('Question projections', () => {
  test('toPublicJSON omits the answer key (students must not receive it)', () => {
    const q = new Question({ prompt: 'What is 1/2 + 1/4?', options: ['2/6', '3/4'], correctOption: '3/4' });
    expect(q.toPublicJSON()).not.toHaveProperty('correctOption');
    expect(q.toPublicJSON().prompt).toBe('What is 1/2 + 1/4?');
  });

  test('toJSON round-trips through the domain object', () => {
    const q = new Question({ prompt: 'What is 1/2 + 1/4?', options: ['2/6', '3/4'], correctOption: '3/4' });
    expect(Question.fromJSON(JSON.parse(JSON.stringify(q.toJSON()))).correctOption).toBe('3/4');
  });
});

describe('seedQuestions default bank', () => {
  test('builds the requested number of questions with valid shape', () => {
    const set = buildDefaultQuestionSet(8);
    expect(set).toHaveLength(8);
    set.forEach((q) => {
      expect(q.prompt.length).toBeGreaterThan(3);
      expect(q.options.length).toBeGreaterThanOrEqual(2);
      expect(q.options).toContain(q.correctOption);
      expect(['easy', 'medium', 'hard']).toContain(q.difficulty);
    });
  });

  test('every seeded question validates', () => {
    buildDefaultQuestionSet(20).forEach((raw) => {
      expect(new Question(raw).validate().valid).toBe(true);
    });
  });

  test('the bank ramps in difficulty across the round', () => {
    const set = buildDefaultQuestionSet(10);
    expect(set[0].difficulty).toBe('easy');
    expect(set[5].difficulty).toBe('medium');
    expect(set[9].difficulty).toBe('hard');
  });
});

function build() {
  const pool = new FakePgPool();
  const redis = new FakeRedisClient();
  const cache = createFakeCache(redis);
  const messaging = createFakeMessaging();
  const search = createFakeSearch();
  const repository = new QuestionRepository({ pool, cache, search, logger: silentLogger, schema: 'question' });
  const service = new QuestionService({ repository, messaging, metrics: null, logger: silentLogger, config });
  return { pool, redis, cache, messaging, search, repository, service };
}

describe('QuestionService CRUD (SequenceDiagram2: Admin ->> Question: update())', () => {
  test('create() persists and publishes question.updated', async () => {
    const { service, pool, messaging } = build();
    const created = await service.create({
      prompt: 'What is 1/3 + 1/3?', options: ['2/3', '1/6'], correctOption: '2/3', difficulty: 'easy',
    });

    expect(created.prompt).toBe('What is 1/3 + 1/3?');
    expect(pool.questions).toHaveLength(1);
    expect(messaging.events(config.rabbitmq.events.questionUpdated)).toHaveLength(1);
    expect(messaging.events(config.rabbitmq.events.questionUpdated)[0].payload.action).toBe('created');
  });

  test('create() rejects an invalid question with a 400', async () => {
    const { service } = build();
    await expect(service.create({ prompt: 'x', options: ['a'], correctOption: 'a' })).rejects.toMatchObject({
      status: 400,
      code: 'invalid_question',
    });
  });

  test('update() returns the merged, re-validated question', async () => {
    const { service } = build();
    const created = await service.create({
      prompt: 'What is 1/3 + 1/3?', options: ['2/3', '1/6'], correctOption: '2/3',
    });
    const updated = await service.update(created.id, { prompt: 'What is 1/4 + 1/4?' });
    expect(updated.prompt).toBe('What is 1/4 + 1/4?');
  });

  test('update() on an unknown question is a 404', async () => {
    const { service } = build();
    await expect(service.update('nope', { prompt: 'What is 1/2?' })).rejects.toMatchObject({
      status: 404,
      code: 'question_not_found',
    });
  });

  test('remove() soft-deletes so history stays durable', async () => {
    const { service, pool } = build();
    const created = await service.create({
      prompt: 'What is 1/3 + 1/3?', options: ['2/3', '1/6'], correctOption: '2/3',
    });
    const removed = await service.remove(created.id);
    expect(removed.active).toBe(false);
    // Row is still present: deactivation, not deletion (ASR-1).
    expect(pool.questions).toHaveLength(1);
    expect(pool.questions[0].active).toBe(false);
  });

  test('remove() on an unknown question is a 404', async () => {
    const { service } = build();
    await expect(service.remove('nope')).rejects.toMatchObject({ status: 404 });
  });
});

describe('QuestionService read paths', () => {
  test('getPrompt() returns the public projection without the answer key', async () => {
    const { service } = build();
    const created = await service.create({
      prompt: 'What is 1/3 + 1/3?', options: ['2/3', '1/6'], correctOption: '2/3',
    });
    const prompt = await service.getPrompt(created.id);
    expect(prompt.prompt).toBe('What is 1/3 + 1/3?');
    expect(prompt).not.toHaveProperty('correctOption');
  });

  test('getPrompt() on an unknown question is a 404', async () => {
    const { service } = build();
    await expect(service.getPrompt('nope')).rejects.toMatchObject({ status: 404 });
  });

  test('checkAnswer() grades and publishes the outcome without leaking the answer', async () => {
    const { service, messaging } = build();
    const created = await service.create({
      prompt: 'What is 1/3 + 1/3?', options: ['2/3', '1/6'], correctOption: '2/3',
    });
    const result = await service.checkAnswer(created.id, '2/3');

    expect(result.correct).toBe(true);
    expect(result.questionId).toBe(created.id);
    const published = messaging.events(config.rabbitmq.events.answerSubmitted)[0].payload;
    expect(published.correct).toBe(true);
    // Privacy/security: the submitted free-text answer is not forwarded.
    expect(published).not.toHaveProperty('answer');
  });

  test('checkAnswer() on an unknown question is a 404', async () => {
    const { service } = build();
    await expect(service.checkAnswer('nope', '2/3')).rejects.toMatchObject({ status: 404 });
  });

  test('list() paginates and never exposes answer keys', async () => {
    const { service } = build();
    await service.create({ prompt: 'What is 1/3 + 1/3?', options: ['2/3', '1/6'], correctOption: '2/3' });
    await service.create({ prompt: 'What is 1/5 + 1/5?', options: ['2/5', '1/10'], correctOption: '2/5' });

    const page = await service.list({ limit: 1, offset: 0 });
    expect(page.questions).toHaveLength(1);
    expect(page.limit).toBe(1);
    expect(page.offset).toBe(0);
    expect(page.questions[0]).not.toHaveProperty('correctOption');
  });

  test('listForAdmin() includes the answer key for the admin actor', async () => {
    const { service } = build();
    await service.create({ prompt: 'What is 1/3 + 1/3?', options: ['2/3', '1/6'], correctOption: '2/3' });
    const adminPage = await service.listForAdmin({ limit: 10 });
    expect(adminPage.questions[0]).toHaveProperty('correctOption');
  });

  test('search() delegates to Elasticsearch (NFR-1)', async () => {
    const { service, search } = build();
    await search.indexDocument('q1', { prompt: 'What is 1/3 + 1/3?' });
    await search.indexDocument('q2', { prompt: 'What is 2/5 + 1/5?' });

    const result = await service.search('1/3');
    expect(result.engine).toBe('elasticsearch');
    expect(result.total).toBe(1);
    expect(result.results[0].prompt).toBe('What is 1/3 + 1/3?');
  });
});

describe('ASR-1: question data durability and recoverability', () => {
  test('durabilityStatus() reports replication, recovery point and RPO/RTO', async () => {
    const { service } = build();
    await service.create({ prompt: 'What is 1/3 + 1/3?', options: ['2/3', '1/6'], correctOption: '2/3' });

    const status = await service.durabilityStatus();
    expect(status.component).toBe('QuestionComponent');
    expect(status.requirement).toBe('ASR-1');
    expect(status.persistedQuestions).toBe(1);
    expect(status.replication).toHaveProperty('standbys');
    expect(status.replication).toHaveProperty('healthy');
    expect(status.recoveryPoint).toHaveProperty('wal_lsn');
    // Section G: RTO 1 hour, RPO 1 hour.
    expect(status.rpoTargetHours).toBe(1);
    expect(status.rtoTargetHours).toBe(1);
  });

  test('seed() populates an empty bank', async () => {
    const { service, pool } = build();
    const result = await service.seed();
    expect(result.skipped).toBe(false);
    expect(result.seeded).toBeGreaterThan(0);
    expect(pool.questions.length).toBe(result.seeded);
  });

  test('seed() is idempotent: a second call is skipped unless forced', async () => {
    const { service } = build();
    await service.seed();
    const second = await service.seed();
    expect(second.skipped).toBe(true);
    expect(second.seeded).toBe(0);
  });

  test('seed() repopulates after a restore (recoverability)', async () => {
    const { service, pool } = build();
    await service.seed();
    // Simulate a restore that lost everything.
    pool.questions = [];
    const recovered = await service.seed();
    expect(recovered.seeded).toBeGreaterThan(0);
    expect(pool.questions.length).toBeGreaterThan(0);
  });

  test('seeded questions are indexed in Elasticsearch', async () => {
    const { service, search } = build();
    await service.seed();
    expect(search.indexed.size).toBeGreaterThan(0);
  });

  test('gets and reads survive a cold cache by falling back to PostgreSQL', async () => {
    const { service, repository, cache } = build();
    const created = await service.create({
      prompt: 'What is 1/3 + 1/3?', options: ['2/3', '1/6'], correctOption: '2/3',
    });
    await cache.del(`question:${created.id}`);

    const loaded = await repository.findById(created.id);
    expect(loaded.prompt).toBe('What is 1/3 + 1/3?');
  });
});

'use strict';

/**
 * UserComponent tests.
 *
 * Covers:
 *   - `User` / `Admin`, the two classes in the ClassDiagram (view 2)
 *   - section F security: OAuth2 authn/authz, secure password storage,
 *     refresh-token rotation, secret handling
 *   - the UseCaseDiagram Admin actor's Update Questions permission
 */
const { User, Admin } = require('../../services/user/src/domain/user');
const { UserService } = require('../../services/user/src/service/userService');
const { UserRepository } = require('../../services/user/src/repository/userRepository');
const shared = require('../../shared/src');
const config = require('../../shared/src/config');
const {
  FakePgPool,
  FakeRedisClient,
  createFakeCache,
  createFakeMessaging,
} = require('../helpers/fakes');

const silentLogger = { info() {}, debug() {}, warn() {}, error() {} };

function build() {
  const pool = new FakePgPool();
  const redis = new FakeRedisClient();
  const cache = createFakeCache(redis);
  const messaging = createFakeMessaging();
  const repository = new UserRepository({ pool, cache, logger: silentLogger, schema: 'user_svc' });
  const service = new UserService({ repository, messaging, metrics: null, logger: silentLogger, config });
  return { pool, redis, cache, messaging, repository, service };
}

describe('User (ClassDiagram: class User)', () => {
  test('has the diagram attributes id and username', () => {
    const user = new User({ username: 'astro' });
    expect(typeof user.id).toBe('string');
    expect(user.username).toBe('astro');
    expect(user.role).toBe('student');
  });

  test('setPassword stores a salted hash, never the plaintext', () => {
    const user = new User({ username: 'astro' });
    user.setPassword('correct-horse-battery');

    expect(user.passwordHash).toBeDefined();
    expect(user.passwordSalt).toBeDefined();
    expect(user.passwordHash).not.toContain('correct-horse-battery');
    // toJSON must never carry credential material.
    expect(JSON.stringify(user.toJSON())).not.toContain(user.passwordHash);
    expect(user.toJSON()).not.toHaveProperty('passwordHash');
    expect(user.toJSON()).not.toHaveProperty('passwordSalt');
  });

  test('two users with the same password get different salts and hashes', () => {
    const a = new User({ username: 'a' }).setPassword('same-password-here');
    const b = new User({ username: 'b' }).setPassword('same-password-here');
    expect(a.passwordSalt).not.toBe(b.passwordSalt);
    expect(a.passwordHash).not.toBe(b.passwordHash);
  });

  test('rejects a password shorter than 8 characters', () => {
    const user = new User({ username: 'astro' });
    expect(() => user.setPassword('short')).toThrow(/at least 8 characters/);
    try {
      user.setPassword('short');
    } catch (err) {
      expect(err.status).toBe(400);
      expect(err.code).toBe('weak_password');
    }
  });

  test('verifyPassword accepts the right password and rejects others', () => {
    const user = new User({ username: 'astro' }).setPassword('correct-horse-battery');
    expect(user.verifyPassword('correct-horse-battery')).toBe(true);
    expect(user.verifyPassword('wrong-horse-battery')).toBe(false);
  });

  test('verifyPassword returns false when no password is set, rather than throwing', () => {
    expect(new User({ username: 'astro' }).verifyPassword('anything')).toBe(false);
    expect(new User({ username: 'astro' }).verifyPassword(null)).toBe(false);
  });

  test('playGame(game) delegates to Game.play() (ClassDiagram signature)', () => {
    const game = { play: jest.fn(), state: 'Playing' };
    const user = new User({ username: 'astro' });
    user.playGame(game);
    expect(game.play).toHaveBeenCalledTimes(1);
    expect(typeof user.lastPlayedAt).toBe('string');
  });

  test('playGame() rejects a non-Game argument', () => {
    const user = new User({ username: 'astro' });
    expect(() => user.playGame(null)).toThrow(/requires a Game instance/);
    expect(() => user.playGame({})).toThrow(/requires a Game instance/);
  });

  test('viewScore(game) returns the game score (ClassDiagram signature)', () => {
    const user = new User({ username: 'astro' });
    expect(user.viewScore({ viewScore: () => 42 })).toBe(42);
  });

  test('scopes follow from the role', () => {
    expect(new User({ username: 's', role: 'student' }).scopes).toContain('game:play');
    expect(new User({ username: 's', role: 'student' }).scopes).not.toContain('questions:write');
    expect(new Admin({ username: 'a' }).scopes).toContain('questions:write');
  });

  test('fromJSON rehydrates a persisted row', () => {
    const user = new User({ username: 'astro' });
    expect(User.fromJSON(JSON.stringify(user.toJSON())).username).toBe('astro');
  });
});

describe('Admin (ClassDiagram: class Admin, Update Questions)', () => {
  test('is an admin-role User', () => {
    const admin = new Admin({ username: 'root' });
    expect(admin.role).toBe('admin');
    expect(admin.isAdmin()).toBe(true);
  });

  test('updateQuestions() validates and serialises every question', () => {
    const admin = new Admin({ username: 'root' });
    const valid = {
      validate: () => ({ valid: true, errors: [] }),
      toJSON: () => ({ id: 'q1', prompt: 'What is 1/2?' }),
    };
    const result = admin.updateQuestions([valid]);
    expect(result).toEqual([{ id: 'q1', prompt: 'What is 1/2?' }]);
    expect(typeof admin.updatedQuestionsAt).toBe('string');
  });

  test('updateQuestions() rejects an invalid question', () => {
    const admin = new Admin({ username: 'root' });
    const invalid = { validate: () => ({ valid: false, errors: ['prompt too short'] }) };
    expect(() => admin.updateQuestions([invalid])).toThrow(/prompt too short/);
  });

  test('updateQuestions() rejects a non-array argument', () => {
    expect(() => new Admin({ username: 'root' }).updateQuestions('nope')).toThrow(/array of questions/);
  });
});

describe('OAuth2 authentication (section F)', () => {
  test('register() then authenticate() issues a usable bearer token', async () => {
    const { service } = build();
    await service.register({ username: 'astro', password: 'a-good-password' });
    const tokens = await service.authenticate({ username: 'astro', password: 'a-good-password' });

    expect(tokens.token_type).toBe('Bearer');
    expect(tokens.expires_in).toBe(3600);
    expect(tokens.access_token).toBeTruthy();
    expect(tokens.refresh_token).toBeTruthy();
    expect(tokens.user.username).toBe('astro');
    expect(tokens.user).not.toHaveProperty('passwordHash');

    const claims = await shared.oauth2.verifyToken(tokens.access_token);
    expect(claims.username).toBe('astro');
    expect(claims.scope).toContain('game:play');
  });

  test('authenticate() rejects a wrong password with invalid_grant', async () => {
    const { service } = build();
    await service.register({ username: 'astro', password: 'a-good-password' });
    await expect(service.authenticate({ username: 'astro', password: 'nope-nope-nope' })).rejects.toMatchObject({
      status: 401,
      code: 'invalid_grant',
    });
  });

  test('authenticate() rejects an unknown user without revealing that it is unknown', async () => {
    const { service } = build();
    await expect(service.authenticate({ username: 'ghost', password: 'a-good-password' })).rejects.toMatchObject({
      status: 401,
      code: 'invalid_grant',
    });
  });

  test('authenticate() refuses a disabled account', async () => {
    const { service, pool } = build();
    await service.register({ username: 'astro', password: 'a-good-password' });
    pool.users[0].active = false;
    await expect(service.authenticate({ username: 'astro', password: 'a-good-password' })).rejects.toMatchObject({
      status: 403,
      code: 'account_disabled',
    });
  });

  test('register() rejects a duplicate username with 409', async () => {
    const { service } = build();
    await service.register({ username: 'astro', password: 'a-good-password' });
    await expect(service.register({ username: 'astro', password: 'another-password' })).rejects.toMatchObject({
      status: 409,
      code: 'user_exists',
    });
  });

  test('register() rejects a too-short username and an unknown role', async () => {
    const { service } = build();
    await expect(service.register({ username: 'ab', password: 'a-good-password' })).rejects.toMatchObject({ status: 400 });
    await expect(
      service.register({ username: 'astro', password: 'a-good-password', role: 'wizard' }),
    ).rejects.toMatchObject({ status: 400 });
  });

  test('registering an admin yields the Admin domain class', async () => {
    const { service } = build();
    const created = await service.register({ username: 'root', password: 'a-good-password', role: 'admin' });
    expect(created.role).toBe('admin');
    expect(created.scopes).toContain('questions:write');
  });

  test('authenticate() publishes user.authenticated', async () => {
    const { service, messaging } = build();
    await service.register({ username: 'astro', password: 'a-good-password' });
    await service.authenticate({ username: 'astro', password: 'a-good-password' });
    const events = messaging.events(config.rabbitmq.events.userAuthenticated);
    expect(events).toHaveLength(1);
    expect(events[0].payload.username).toBe('astro');
  });

  test('a requested scope narrower than the role is honoured', async () => {
    const { service } = build();
    await service.register({ username: 'astro', password: 'a-good-password' });
    const tokens = await service.authenticate({
      username: 'astro', password: 'a-good-password', scope: 'help:read',
    });
    expect(tokens.scope).toBe('help:read');
  });
});

describe('OAuth2 client_credentials grant (service-to-service)', () => {
  test('correct client credentials yield an admin-scoped service token', () => {
    const { service } = build();
    const token = service.issueServiceToken({
      clientId: process.env.SERVICE_CLIENT_ID || 'spacefractions-internal',
      clientSecret: process.env.SERVICE_CLIENT_SECRET || 'internal-secret-change-me',
    });
    expect(token.access_token).toBeTruthy();
    expect(token.scope).toContain('questions:write');
  });

  test('a wrong client secret is rejected with invalid_client', () => {
    const { service } = build();
    expect(() => service.issueServiceToken({ clientId: 'spacefractions-internal', clientSecret: 'wrong' }))
      .toThrow(/Invalid client credentials/);
  });

  test('missing client credentials are rejected', () => {
    const { service } = build();
    expect(() => service.issueServiceToken({})).toThrow(/Invalid client credentials/);
  });
});

describe('OAuth2 refresh_token grant with rotation (section F rotation policy)', () => {
  test('a refresh token yields a new access token', async () => {
    const { service } = build();
    await service.register({ username: 'astro', password: 'a-good-password' });
    const first = await service.authenticate({ username: 'astro', password: 'a-good-password' });

    const refreshed = await service.refresh({ refreshToken: first.refresh_token });
    expect(refreshed.access_token).toBeTruthy();
    expect(refreshed.refresh_token).not.toBe(first.refresh_token);
  });

  test('the presented refresh token is revoked after use (rotation)', async () => {
    const { service } = build();
    await service.register({ username: 'astro', password: 'a-good-password' });
    const first = await service.authenticate({ username: 'astro', password: 'a-good-password' });
    await service.refresh({ refreshToken: first.refresh_token });

    await expect(service.refresh({ refreshToken: first.refresh_token })).rejects.toMatchObject({
      status: 401,
      code: 'invalid_grant',
    });
  });

  test('a missing refresh token is a 400', async () => {
    const { service } = build();
    await expect(service.refresh({})).rejects.toMatchObject({ status: 400, code: 'invalid_request' });
  });

  test('an unknown refresh token is rejected', async () => {
    const { service } = build();
    await expect(service.refresh({ refreshToken: 'made-up' })).rejects.toMatchObject({ status: 401 });
  });

  test('refresh tokens are stored hashed, not in plaintext', async () => {
    const { service, pool } = build();
    await service.register({ username: 'astro', password: 'a-good-password' });
    const tokens = await service.authenticate({ username: 'astro', password: 'a-good-password' });

    expect(pool.refreshTokens).toHaveLength(1);
    expect(pool.refreshTokens[0].token_hash).not.toBe(tokens.refresh_token);
  });

  test('purgeExpiredRefreshTokens removes expired rows', async () => {
    const { service, repository, pool } = build();
    await service.register({ username: 'astro', password: 'a-good-password' });
    await service.authenticate({ username: 'astro', password: 'a-good-password' });
    pool.refreshTokens[0].expires_at = new Date(Date.now() - 1000).toISOString();

    const purged = await repository.purgeExpiredRefreshTokens();
    expect(purged).toBe(1);
  });
});

describe('Authorization decisions (section F authn/authz)', () => {
  test('authorise() grants a scope the role holds', async () => {
    const { service } = build();
    const user = await service.register({ username: 'astro', password: 'a-good-password' });
    const decision = await service.authorise(user.id, 'game:play');
    expect(decision.authorised).toBe(true);
  });

  test('authorise() denies a scope the role does not hold', async () => {
    const { service } = build();
    const user = await service.register({ username: 'astro', password: 'a-good-password' });
    const decision = await service.authorise(user.id, 'questions:write');
    expect(decision.authorised).toBe(false);
  });

  test('authorise() grants an admin everything', async () => {
    const { service } = build();
    const admin = await service.register({ username: 'root', password: 'a-good-password', role: 'admin' });
    const decision = await service.authorise(admin.id, 'questions:write');
    expect(decision.authorised).toBe(true);
  });

  test('authorise() for an unknown user is a denial, not an error', async () => {
    const { service } = build();
    const decision = await service.authorise('ghost', 'game:play');
    expect(decision.authorised).toBe(false);
    expect(decision.reason).toBe('user_not_found');
  });

  test('an issued admin token actually satisfies the admin route guard', async () => {
    const { service } = build();
    await service.register({ username: 'root', password: 'a-good-password', role: 'admin' });
    const tokens = await service.authenticate({ username: 'root', password: 'a-good-password' });

    const claims = await shared.oauth2.verifyToken(tokens.access_token);
    expect(claims.roles).toContain('admin');
    expect(claims.scope).toContain('questions:write');
  });

  test('a student token does not satisfy the admin route guard', async () => {
    const { service } = build();
    await service.register({ username: 'astro', password: 'a-good-password' });
    const tokens = await service.authenticate({ username: 'astro', password: 'a-good-password' });

    const claims = await shared.oauth2.verifyToken(tokens.access_token);
    expect(claims.scope).not.toContain('questions:write');
  });
});

describe('UserService reads and bootstrap', () => {
  test('me() returns the current user', async () => {
    const { service } = build();
    const user = await service.register({ username: 'astro', password: 'a-good-password' });
    expect((await service.me(user.id)).username).toBe('astro');
  });

  test('me() on an unknown id is a 404', async () => {
    const { service } = build();
    await expect(service.me('ghost')).rejects.toMatchObject({ status: 404 });
  });

  test('list() returns a page of users and a total', async () => {
    const { service } = build();
    await service.register({ username: 'astro', password: 'a-good-password' });
    await service.register({ username: 'comet', password: 'a-good-password' });
    const page = await service.list({ limit: 10, offset: 0 });
    expect(page.users).toHaveLength(2);
    expect(page.total).toBe(2);
  });

  test('list() never leaks password material', async () => {
    const { service } = build();
    await service.register({ username: 'astro', password: 'a-good-password' });
    const page = await service.list({ limit: 10, offset: 0 });
    expect(page.users[0]).not.toHaveProperty('passwordHash');
  });

