  1	'use strict';
  2	
  3	const { User } = require('../domain/user');
  4	
  5	/**
  6	 * UserRepository - persistence for UserComponent.
  7	 *
  8	 * Section F: "Implement OAuth2 for authentication and authorization",
  9	 * "Use secure password storage and transmission",
 10	 * "Use a secrets manager like Hashicorp's Vault", "Rotate secrets regularly".
 11	 *
 12	 * Refresh tokens are stored as SHA-256 hashes (never raw) so a database leak
 13	 * does not hand over live credentials; that is the rotation-friendly design
 14	 * section F implies.
 15	 */
 16	class UserRepository {
 17	  constructor({ pool, cache, logger, schema = 'user', metrics = null }) {
 18	    this.pool = pool;
 19	    this.cache = cache;
 20	    this.logger = logger;
 21	    this.schema = schema;
 22	    this.metrics = metrics;
 23	  }
 24	
 25	  get usersTable() {
 26	    return `${this.schema}.users`;
 27	  }
 28	
 29	  get refreshTable() {
 30	    return `${this.schema}.refresh_tokens`;
 31	  }
 32	
 33	  async insert(user) {
 34	    const sql = `
 35	      INSERT INTO ${this.usersTable}
 36	        (user_uid, username, role, password_hash, password_salt, email, display_name, active)
 37	      VALUES ($1,$2,$3,$4,$5,$6,$7,$8)
 38	      RETURNING id, user_uid, created_at, updated_at
 39	    `;
 40	    const params = [
 41	      user.id,
 42	      user.username,
 43	      user.role,
 44	      user.passwordHash,
 45	      user.passwordSalt,
 46	      user.email,
 47	      user.displayName,
 48	      user.active,
 49	    ];
 50	    const op = () => this.pool.query(sql, params);
 51	    const { rows } = this.metrics
 52	      ? await this.metrics.timeExternal('postgres', 'insertUser', op)
 53	      : await op();
 54	    return rows[0];
 55	  }
 56	
 57	  async findByUsername(username) {
 58	    const op = () => this.pool.query(
 59	      `SELECT * FROM ${this.usersTable} WHERE lower(username) = lower($1) LIMIT 1`,
 60	      [username],
 61	    );
 62	    const { rows } = await this.metrics
 63	      ? await this.metrics.timeExternal('postgres', 'findUserByUsername', op)
 64	      : await op();
 65	    return rows[0] ? User.fromJSON(rowToUser(rows[0])) : null;
 66	  }
 67	
 68	  async findById(userId) {
 69	    const cacheKey = `user:${userId}`;
 70	    if (this.cache) {
 71	      const cached = await this.cache.get(cacheKey);
 72	      if (cached) return User.fromJSON(cached);
 73	    }
 74	    const op = () => this.pool.query(
 75	      `SELECT * FROM ${this.usersTable} WHERE user_uid = $1 LIMIT 1`,
 76	      [userId],
 77	    );
 78	    const { rows } = await this.metrics
 79	      ? await this.metrics.timeExternal('postgres', 'findUserById', op)
 80	      : await op();
 81	    if (!rows[0]) return null;
 82	    const user = User.fromJSON(rowToUser(rows[0]));
 83	    if (this.cache) await this.cache.set(cacheKey, user.toJSON(), 300);
 84	    return user;
 85	  }
 86	
 87	  async count() {
 88	    const { rows } = await this.pool.query(`SELECT COUNT(*)::int AS count FROM ${this.usersTable}`);
 89	    return rows[0].count;
 90	  }
 91	
 92	  async setActive(userId, active) {
 93	    const { rows } = await this.pool.query(
 94	      `UPDATE ${this.usersTable} SET active = $2, updated_at = NOW()
 95	        WHERE user_uid = $1 RETURNING user_uid`,
 96	      [userId, active],
 97	    );
 98	    if (this.cache) await this.cache.del(`user:${userId}`);
 99	    return rows.length > 0;
100	  }
101	
102	  /** Store only the SHA-256 hash of a refresh token. */
103	  async storeRefreshToken(userId, token, expiresAt) {
104	    const hash = hashToken(token);
105	    await this.pool.query(
106	      `INSERT INTO ${this.refreshTable} (user_uid, token_hash, expires_at, revoked)
107	       VALUES ($1,$2,$3,FALSE)
108	       ON CONFLICT (token_hash) DO NOTHING`,
109	      [userId, hash, expiresAt],
110	    );
111	    return hash;
112	  }
113	
114	  async findRefreshToken(token) {
115	    const { rows } = await this.pool.query(
116	      `SELECT * FROM ${this.refreshTable}
117	        WHERE token_hash = $1 AND revoked = FALSE AND expires_at > NOW() LIMIT 1`,
118	      [hashToken(token)],
119	    );
120	    return rows[0] || null;
121	  }
122	
123	  async revokeRefreshToken(token) {
124	    await this.pool.query(
125	      `UPDATE ${this.refreshTable} SET revoked = TRUE WHERE token_hash = $1`,
126	      [hashToken(token)],
127	    );
128	  }
129	
130	  /** Section F: "Rotate secrets regularly" - purge expired refresh tokens. */
131	  async purgeExpiredRefreshTokens() {
132	    const { rowCount } = await this.pool.query(
133	      `DELETE FROM ${this.refreshTable} WHERE expires_at <= NOW() OR revoked = TRUE`,
134	    );
135	    return rowCount;
136	  }
137	}
138	
139	function hashToken(token) {
140	  // eslint-disable-next-line global-require
141	  return require('crypto').createHash('sha256').update(String(token)).digest('hex');
142	}
143	
144	function rowToUser(row) {
145	  return {
146	    id: row.user_uid,
147	    username: row.username,
148	    role: row.role,
149	    passwordHash: row.password_hash,
150	    passwordSalt: row.password_salt,
151	    email: row.email,
152	    displayName: row.display_name,
153	    active: row.active,
154	    createdAt: row.created_at ? new Date(row.created_at).toISOString() : undefined,
155	    updatedAt: row.updated_at ? new Date(row.updated_at).toISOString() : undefined,
156	  };
157	}
158	
159	module.exports = { UserRepository, rowToUser, hashToken };

