 2	
 3	const { createClient } = require('redis');
 4	const config = require('../config');
 5	
 6	/**
 7	 * Redis client (spec section D: "Cache: Redis 6-7").
 8	 *
 9	 * Section D's caching strategy is explicit:
10	 *   - "Cache game state in Redis"
11	 *   - "Use PostgreSQL for data persistence"
12	 * So Redis is a cache-aside layer in front of PostgreSQL, never the source of
13	 * truth.
14	 */
15	function createRedisClient(logger) {
16	  const client = createClient({
17	    url: config.redis.url,
18	    socket: {
19	      connectTimeout: config.redis.connectTimeoutMs,
20	      reconnectStrategy: (retries) => Math.min(retries * 100, 3000),
21	    },
22	  });
23	
24	  client.on('error', (err) => {
25	    logger && logger.warn({ err: err.message }, 'redis client error');
26	  });
27	
28	  // Connect eagerly but never let a Redis outage crash a request path.
29	  client.connect().catch((err) => {
30	    logger && logger.warn({ err: err.message }, 'redis initial connect failed; cache disabled');
31	  });
32	
33	  return client;
34	}
35	
36	/**
37	 * Cache-aside helper. If Redis is unavailable the factory always falls through
38	 * to the loader so PostgreSQL remains authoritative (ASR-1 data durability).
39	 */
40	function createCacheAside(client, logger, { prefix = 'spacefractions', ttlSeconds = 300 } = {}) {
41	  function key(k) {
42	    return `${prefix}:${k}`;
43	  }
44	
45	  return {
46	    async get(k) {
47	      if (!client || !client.isReady) return null;
48	      try {
49	        const raw = await client.get(key(k));
50	        return raw ? JSON.parse(raw) : null;
51	      } catch (err) {
52	        logger && logger.warn({ err: err.message, key: k }, 'cache read miss (redis unavailable)');
53	        return null;
54	      }
55	    },
56	
57	    async set(k, value, ttl = ttlSeconds) {
58	      if (!client || !client.isReady) return false;
59	      try {
60	        await client.set(key(k), JSON.stringify(value), { EX: ttl });
61	        return true;
62	      } catch (err) {
63	        logger && logger.warn({ err: err.message, key: k }, 'cache write failed');
64	        return false;
65	      }
66	    },
67	
68	    async del(k) {
69	      if (!client || !client.isReady) return false;
70	      try {
71	        await client.del(key(k));
72	        return true;
73	      } catch (err) {
74	        logger && logger.warn({ err: err.message, key: k }, 'cache delete failed');
75	        return false;
76	      }
77	    },
78	
79	    /**
80	     * read-through: return cached value if present, otherwise call loader and
81	     * populate the cache.
82	     */
83	    async remember(k, loader, ttl = ttlSeconds) {
84	      const cached = await this.get(k);
85	      if (cached !== null && cached !== undefined) return cached;
86	      const fresh = await loader();
87	      if (fresh !== null && fresh !== undefined) await this.set(k, fresh, ttl);
88	      return fresh;
89	    },
90	  };
91	}
92	
93	module.exports = { createRedisClient, createCacheAside };

